	-- Treasure/rare how-to notities
	ACH_NOTE_ROOKERY = "Op het zwevende Sunwing Rookery-platform (Falconwing Square): koop Tasty Meat bij Farstrider Aerieminder (bij het balkon) en leg het naast de Mischievous Chick tegenover de kist om de sleutel te krijgen. Beloning: Sunwing Hatchling-huisdier.",
