	PROF_GENERATE_TREASURES_BTN = "Genereer Treasure-route",
	PROF_GENERATE_BOOKS_BTN = "Genereer Book-route",
	PROFACAD_ADVISE_NEXT_FMT = "Advies: volgende punten in %s (root %d/%d).",
	PROFACAD_ADVISE_NEXT_POINTS_FMT = "Advies: je volgende punten in %s (root %d/%d) — met ongeveer %d werkt het al; deze stap vinkt pas af als de tak vol is. Hang in het spel boven de node voor het exacte getal; de gidsen spreken elkaar tegen.",
	PROFACAD_ADVISE_NEXT_OPEN_FMT = "Advies: open %s — en stop daar. Het ontgrendelen is wat oplevert; punten daarbovenop zijn een gok op materiaalprijzen.",
	PROFACAD_ADVISE_PICK_ONE_FMT = "Advies: je volgende punten gaan in ÉÉN hiervan — %s. Ze zijn niet uitwisselbaar, dus hover ze in het spel en neem degene die past bij wat je echt doet.",
	PROFACAD_ADVISE_GOALS_FMT = "Vanaf hier splitst de route, en die twee verschillen echt. %s",
	PROFACAD_ADVISE_GOAL_LINE_FMT = "%s %s (root %d/%d).",
	PROFACAD_GOAL_GOLD = "Verkopen aan anderen:",
	PROFACAD_GOAL_SELF = "Jezelf en je gilde uitrusten:",
	PROFACAD_ADVISE_SEE_COURSE = "Open Course (101) hierboven: die noemt de tak en legt uit waarom.",
	PROFACAD_ADVISE_NODE_FINISH_FMT = "Hier houdt het geverifieerde advies op. Je punten gingen tot nu toe in %s (%d/%d).",
	PROFACAD_ADVISE_NODE_FMT = "Advies: zet je volgende punten in %s (%d/%d).",
	PROFACAD_CHOICES_HEADER = "Losse nodes in je trees die nog niet vol zijn:",
	PROFACAD_CHOICES_HEADER_MORE_FMT = "Losse nodes in je trees die nog niet vol zijn (%d van %d):",
	PROFACAD_CHOICE_FMT = "%s (%d/%d)",
	PROFACAD_ADVISE_LOCKED = "Er kan nog geen enkele specialisatie punten aannemen, dus valt er niets te adviseren. Werk eerst je skill omhoog — de eerste keuze gaat open op 25. Je Knowledge blijft tot dan gewoon staan; er gaat niets verloren.",
	PROFACAD_ADVISE_DONE = "Advies: de aanbevolen roots zijn klaar.",
	PROFHUB_TAB_OVERVIEW = "Overzicht",
	PROFHUB_TAB_TREASURES = "Treasures & Books",
	PROFHUB_TAB_COURSE = "Cursus (101)",
	PROFHUB_OVERVIEW_HINT = "Treasures & Books: eenmalige KP-schatten en boeken met waypoints. Cursus (101): de beginnerscursus — hoofdstukken verschijnen voor je eigen professies. Wekelijkse KP: onbestede Knowledge en je trainer-weekly staan op This Week en naast het professievenster.",
	INFO_DRAWER_BODY_PROFHUB = "Alles rond professies op één plek. Overzicht toont je professies, Knowledge Points en live tree-advies; Treasures & Books trackt eenmalige KP-pickups met waypoints; Cursus (101) is de beginnerscursus.",
	PROFACAD_CH_KNOWLEDGE_TITLE = "Wat is Knowledge?",
	PROFACAD_CH_KNOWLEDGE_INTRO = "Eerst dit: een professie heeft twee getallen. Skill stijgt vanzelf door te craften. Knowledge is degene die telt — beperkt, grotendeels wekelijks, en bepalend voor wát je kunt maken. Dit hoofdstuk gaat over die tweede.",
	PROFACAD_CH_KNOWLEDGE_BODY = "Je beroep groeit op twee manieren, en dat is precies waar de verwarring zit.\n\nJe |cffffffffSkill|r loopt op door dingen te maken. Dat gaat vanzelf. Daarnaast verzamel je |cffffffffKnowledge Points|r, die je juist niet van craften krijgt maar van opdrachten, schatkisten en boeken — en die geef je uit in een tree, waar je kiest waar jij goed in wordt.\n\nHet beeld dat helpt: |cffffffffskill is hoe vaak je het gedaan hebt, kennis is waar je je in verdiept hebt.|r Twee alchemisten van hetzelfde niveau kunnen totaal verschillende dingen, omdat ze hun kennis ergens anders in gestoken hebben. Dat is ook waarom je niet alles kunt. Je moet kiezen.\n\n|cffffcc00Waar de punten vandaan komen — vijf bronnen, en de eerste is veruit de grootste.|r\n\n1. Opdrachten van het spel zelf (Patron Orders), aan de werkbank van je beroep. Die krijgen hieronder een eigen hoofdstuk, inclusief de valstrik dat je ze beter niet allemaal aan het begin van de week doet.\n2. Alles één keer maken. Elk recept dat je voor het eerst craft levert een punt op. Doe dit vóór je gaat verdelen, dan heb je meer om mee te werken.\n3. Schatten in de wereld. Verspreid over de Midnight-gebieden liggen kisten die punten geven — een flinke buit als je ze nog niet gehad hebt.\n4. Een wekelijkse opdracht bij je leraar, en een treatise die een scribe voor je kan maken.\n5. Reputatieboeken. Bij een paar facties kun je een boek kopen dat er in één klap tien geeft.\n\nCooking, Fishing en Archaeology hebben geen trees en hebben dus helemaal geen punten nodig.\n\nMaak je geen zorgen over \"achterlopen\": gemiste weken komen langzaam terug via een inhaalsysteem, en deze cursus loopt het stap voor stap met je door.",
	PROFACAD_CH_KNOWLEDGE_TASK = "Open je professievenster (standaardtoets: K) en bekijk de Specializations-tab.",
	PROFACAD_CH_GEARUP_TITLE = "Uitrusten: tools, stations & eerste recepten",
	PROFACAD_CH_GEARUP_INTRO = "Professies zijn per uitbreiding gesplitst, dus je venster kan leeg lijken terwijl het gewoon de verkeerde periode toont. Stap één is zorgen dat je naar Midnight kijkt.",
	PROFACAD_CH_GEARUP_BODY = "Eerst dit: het dropdown-menu bovenin het professievenster wisselt tussen uitbreidings-tiers — alles in deze cursus gaat over de MIDNIGHT-tier. Staat die er niet tussen? Leer hem bij de trainers in Silvermoon.\n\nElke professie heeft ook eigen uitrusting — 1 tool en 2 accessoires — in aparte slots bovenin het professievenster (K). Zonder ge-equipte tool kun je veel recepten simpelweg niet craften. De meeste tools en accessoires worden door ÁNDERE professies gemaakt (Blacksmithing, Leatherworking) — koop ze op het veilinghuis onder Profession Equipment of vraag een crafter; de supplies-vendor heeft soms basics. Enchanting is bijzonder en maakt z'n eigen rods: koop de goedkope basis-rod bij de vendor, craft de Runed-versie bij het Enchanter's Lectern (skill 1-trainerrecept), en equip 'm.\n\nGrijze craft-knop? Lees de vereisten-regel in het recept: die vertelt of je een tool mist of bij een station moet staan (aambeeld, lectern, kookvuur...). De stations staan rond de trainerwijk in Silvermoon.\n\nLeer daarna je eerste recepten bij de trainer en craft ze — skill 25 unlockt je specialization-trees, en elke first craft geeft +1 KP.",
	PROFACAD_CH_GEARUP_TASK = "Equip een tool voor elk van je professies.",
	PROFACAD_CH_TREES_TITLE = "Trees kiezen — zonder spijt",
	PROFACAD_CH_TREES_INTRO = "Je specialisatieboom is waar Knowledge heen gaat. Zie het als een talentenboom voor je vak: wat je erin stopt bepaalt wat je kunt maken, en hoe goed.",
	PROFACAD_CH_TREES_ADVANCED = "Waar klik je nou echt? Open je professievenster (dat met je recepten) en kijk naar de tabs onderaan: Recipes, Specializations, Crafting Orders. Specializations is hem - daar staan je bomen en daar geef je Knowledge uit. Er gebeurt niets tot je bevestigt, dus je kunt het gerust eerst openen en rondkijken. Weet je niet welke boom? Kom hier terug: het Professions-overzicht noemt de volgende node zodra het je bomen kan lezen.",
	PROFACAD_CH_TREES_BODY = "Daar staan drie of vier |cffffffffwheels|r naast elkaar. Elke wheel bestaat uit ronde vakjes verbonden door lijntjes, en je herkent er een aan de ring eromheen die voller wordt naarmate je er punten in stopt — hang je er met je muis boven, dan staat er iets als \"3 / 30\": drie punten erin, dertig is vol. Gidsen noemen zo'n vakje een node. Elke wheel heeft één groot vakje in het midden (de root) en kleinere eromheen die pas verschijnen als er in dat middelste genoeg zit. Rondkijken kost niets: er verandert pas iets als je bevestigt.\n\n|cffffcc00De enige regel die telt: verdeel je punten niet.|r\n\nOveral een beetje in stoppen voelt slim. Het is de duurste fout die er is, en iedereen maakt hem. De reden: alles wat er echt toe doet zit achter een |cffffffffdrempel|r. Bij dertig punten gebeurt er iets, bij vijftien gebeurt er niets. Vier half gevulde vakjes leveren dus |cffffffffnul|r op — je hebt honderd punten uitgegeven en kunt nog steeds niks bijzonders.\n\nKies er één. Maak hem af. Ga dan pas verder. Hoe groot zo'n drempel is verschilt per beroep en zelfs per vakje, dus ga niet op een getal uit een gids af: hang erboven en het spel vertelt het je.\n\n|cffffcc00Wat je krijgt als je een tak opent|r is niet wat de meeste mensen verwachten, en het is goed nieuws. Het recept zit meestal aan het |cffffffffopenen|r van een tak, niet aan het volmaken ervan — je opent hem en je kunt het meteen maken. De punten die je er daarna in stopt maken het niet mogelijk, die maken het |cffffffffbeter|r. Het openen kost je ook geen Knowledge Point; daarvoor krijg je aparte ontgrendelingen, op vaste momenten in het middelste vakje. Maar je krijgt er niet oneindig veel: wil je een tweede tak openen, dan moet je eerst verder in het midden. Openen is gratis, maar gerantsoeneerd.\n\n|cffffcc00En sommige dingen staan gewoon uit,|r en dat is de valkuil waarbij mensen denken dat het spel kapot is. Een paar takken zetten iets aan dat daarvoor letterlijk niet bestond. Een ingenieur kan oude spullen recyclen, maar |cffffffffontdekt er pas recepten mee|r nadat er punten in zitten — doe je dat niet, dan recycle je eindeloos zonder resultaat. Een kleermaker ziet de dure stoffen pas vallen zodra de bijbehorende tak geleerd is. Een kruidenplukker kan pas vanaf zijn rijdier plukken als hij er ver genoeg in zit. Lijkt iets \"niet te werken\", kijk dan eerst of het misschien nog aan moet.\n\n|cffffcc00Je hebt één herkansing.|r Sinds patch 12.1 mag je je punten |cfffffffféén keer per beroep|r terugdraaien, bij Theremis in Silvermoon, vlak bij de order-tafel. Eén keer — daarna liggen je keuzes vast. Je verleert ook de recepten die je met die punten had vrijgespeeld; ze komen terug zodra je de punten weer neerzet, maar schrik er niet van. En zenuwachtig hoef je er niet van te worden: blijf je verzamelen, dan kun je op termijn elke tak invullen, dus punten kun je niet echt |cffffffffverspillen|r — alleen op de verkeerde plek hebben in de maanden dat het uitmaakt.\n\nJe krijgt een keuze uit een tree op skill 25, 50, 60 en 75. Het spel bepaalt niet welke; dat doe jij. Zodra je beroepen hebt geven hun eigen hoofdstukken hieronder een concrete starter build, en het Professions-overzicht toont live advies voor je eigen trees.",
	PROFACAD_CH_TREES_TASK = "Bekijk je trees en kies ÉÉN eerste doel — geef nog niets uit.",
	PROFACAD_CH_QUALITY_TITLE = "Kwaliteit — waarom zijn zwaard beter is dan het jouwe",
	PROFACAD_CH_QUALITY_INTRO = "Twee spelers maken hetzelfde item, met hetzelfde recept, en toch is het ene beter. Dat is geen pech en geen bug: gemaakte spullen hebben een kwaliteit.",
	PROFACAD_CH_QUALITY_ADVANCED = "Waar klik je nou eigenlijk? Open een recept in je beroepsvenster en kijk rechts naar het blokje Crafting Details: daar staat Recipe Difficulty tegenover jouw Skill, en dat is het hele rekensommetje in twee getallen. Klik op een grondstof in het recept en je mag zelf kiezen welke kwaliteit materiaal erin gaat — de tooltip zegt \"Left Click to allocate reagent qualities\". Er staat ook een vinkje \"Use Best Quality Reagents\" dat automatisch je beste pakt. Handig, maar het maakt je dure spullen op zonder het nog een keer te vragen.",
	PROFACAD_CH_QUALITY_BODY = "Het beeld dat helpt: het recept zegt |cffffffffwát|r je maakt, de kwaliteit zegt hoe goed het gelukt is. Twee bakkers met hetzelfde recept bakken niet hetzelfde brood.\n\nJe leest het af aan een klein |cffffffffvormpje|r, niet aan een cijfer. In het tekstblokje staat \"Quality:\" met dat teken erachter — een grijs ruitje is laag, een gouden vijfhoekje is hoog. In je beroepsvenster zie je hetzelfde terug als een balk, links het laagste teken en rechts het hoogste, met een wit streepje dat laat zien waar jouw craft ongeveer gaat landen.\n\nHet maakt om drie redenen uit, en de derde overkomt iedereen één keer. Betere uitrusting en sterkere drankjes, uiteraard. Meer goud: hetzelfde recept, Scalewoven Hide, deed 10 goud 94 op de laagste rang en 21 goud 12 op de hoogste — bijna het dubbele, voor dezelfde grondstoffen en dezelfde handeling. Elke rang is ook echt een |cffffffffapart item|r met een eigen plek op het veilinghuis, dus je kunt ze niet door elkaar stapelen. En de derde: vraagt iemand om een bepaalde rang en haal jij die niet, dan |cffffffffkun je die opdracht niet afmaken|r. Niet \"hij wordt minder goed\" — je kunt hem letterlijk niet inleveren.\n\nWat het bepaalt is één getal: je |cffffffffSkill|r op het moment dat je op maken drukt. Elk recept heeft een moeilijkheid. Zit je daar ruim boven, dan haal je de hoogste rang; zit je eronder, dan niet.\n\nDat getal is opgebouwd uit vier dingen. Je basisvaardigheid, die oploopt door dingen te maken en op een gegeven moment vol zit. Je Knowledge Points, die vaardigheid geven bij |cffffffffprecies dát soort recept|r — punten in ringen maken je ringen beter, niet je kettingen. Je beroepsuitrusting: gereedschap en twee accessoires per beroep, in eigen plekken in je uitrustingsscherm, die heel veel mensen gewoon leeg laten. En je grondstoffen, die dezelfde kwaliteitsvormpjes dragen, dus goedkope materialen zijn niet altijd goedkoper.\n\nKom je één stapje tekort, dan is er een noodrem: Concentration. Die heeft hieronder een eigen hoofdstuk.\n\nEén valkuil is het benoemen waard, want hij kost echt geld: |cffffffffhalf gespecialiseerd zijn is duurder dan niet gespecialiseerd zijn|r. Verdeel je je punten over vier takken, dan kom je overal net tekort. Je kunt alles maken op een middelmatige rang, en middelmatig verkoopt niet en wordt bij opdrachten geweigerd.\n\nVerzamel je in plaats van maken, dan heeft je oogst ook rangen — maar in Midnight maar |cfffffffftwee|r, niet de hele ladder. Meer vaardigheid betekent vaker de betere van de twee. Er is geen derde rang om op te jagen.",
	PROFACAD_CH_QUALITY_TASK = "Open een recept en zoek de Quality-balk en het blokje Crafting Details.",
	PROFACAD_CH_STATS_TITLE = "De zes getallen die niemand uitlegt",
	PROFACAD_CH_STATS_INTRO = "Multicraft, Resourcefulness, Deftness. Het spel legt nergens uit wat ze doen, en de meeste spelers zoeken het elke keer opnieuw op.",
	PROFACAD_CH_STATS_ADVANCED = "Waar zie je ze nou eigenlijk? Open een recept in je beroepsvenster en kijk rechts naar het blokje Crafting Details — daar staan de zes als percentages, bijvoorbeeld Resourcefulness 4%, Multicraft 4%, Ingenuity 19%. In datzelfde blokje staat Recipe Difficulty tegenover jouw Skill, en daaronder wat Concentration je zou kosten om de volgende kwaliteitsrang af te dwingen.",
	PROFACAD_CH_STATS_BODY = "Het beeld dat helpt: |cffffffffSkill bepaalt hoe góed het wordt, deze zes bepalen hoe voordelig je er kwam.|r Skill gaat over het resultaat; deze gaan over de weg ernaartoe.\n\nEr zijn er drie voor maken en drie voor verzamelen, dus je hebt ze nooit alle zes tegelijk nodig.\n\nBij maken. |cffffffffResourcefulness|r betekent dat een craft soms minder verbruikt dan zou moeten en jij het materiaal houdt. Dit is de enige die op alles werkt, en de enige die je winst bij opdrachten van anderen verbetert — want de restjes blijven bij jou en niet bij de besteller. |cffffffffMulticraft|r betekent dat er soms meer dan één uit dezelfde grondstoffen rolt. |cffffffffIngenuity|r geeft je een deel van je Concentration terug.\n\nDe valkuil in dat rijtje: |cffffffffMulticraft doet niets bij uitrusting.|r Een extra exemplaar heeft alleen zin bij spullen die je kunt stapelen — drankjes, edelstenen, grondstoffen. Bij een ring of een borstplaat rolt er nooit een tweede uit, dus maak je vooral uitrusting, dan is Multicraft weggegooid. En bij opdrachten van anderen gaan de extra exemplaren naar de |cffffffffbesteller|r, niet naar jou. Dat laatste is wat spelers onderling melden; Blizzard heeft het nooit bevestigd.\n\nBij verzamelen. |cffffffffFinesse|r geeft je er meer per plek, en dat is je volume en dus je goud. |cffffffffPerception|r geeft je een grotere kans op het zeldzame spul in plaats van meer van het gewone. |cffffffffDeftness|r maakt de pluk- of hak-animatie korter.\n\nWelke telt het zwaarst? Dat hangt af van wat je doet, en daar zit het nuttigste inzicht. Bij kruiden is Finesse je stat: je bent per uur veel meer tijd kwijt met zoeken en vliegen dan met plukken, dus sneller plukken lost het verkeerde probleem op. Bij mijnen geldt hetzelfde, en is Perception zwak, want het zeldzame erts waar het je naartoe stuurt heeft weinig gebruik in recepten. |cffffffffBij villen draait het om|r — zodra je op de zeldzame beesten jaagt is Perception juist sterk, want dáár zit de dure buit. Dat is het enige verzamelberoep waar dat zo is. Die drie zijn oordelen over hoe de beroepen spelen, geen getallen die iemand gepubliceerd heeft.\n\nDe waarden komen van twee plekken die je zelf stuurt: je Knowledge Points, want veel takken geven een van deze zes, en je beroepsuitrusting. Kijk bij het uitgeven van een punt dus ook naar wélke stat eronder hangt, en of die past bij wat je echt gaat maken.\n\nAls je maar één ding onthoudt: |cffffffffkijk eerst wát je gaat maken, kies dán je stat.|r Iemand die drankjes verkoopt en iemand die ringen maakt hebben tegengestelde belangen, en een gids die \"Multicraft is het beste\" roept vertelt er niet bij tegen wie hij het heeft.",
	PROFACAD_CH_STATS_TASK = "Open Crafting Details bij een recept en lees je eigen drie percentages.",
	PROFACAD_CH_CONC_TITLE = "Concentration, de noodrem",
	PROFACAD_CH_CONC_INTRO = "Soms kom je één rang tekort, en dan is het zonde om het ding toch maar lager te maken. Daar is Concentration precies voor.",
	PROFACAD_CH_CONC_ADVANCED = "Waar vind je hem nou eigenlijk? In je beroepsvenster is het een balk bovenin met je huidige voorraad, en als je een recept opent staat er een vlammetje naast de maak-knop met wat juist die craft zou kosten. De prijs verschilt per recept, dus lees hem voor je drukt.",
	PROFACAD_CH_CONC_BODY = "Het beeld: |cffffffffhet is een accu die zichzelf vult.|r Je doet er niets voor, hij loopt vanzelf op, en je kunt hem leegtrekken op het moment dat het ertoe doet. Zet je hem in bij het maken, dan is de volgende kwaliteitsrang |cffffffffgegarandeerd|r — geen kans, geen gok. Het spel zegt het zelf: \"Apply 358 concentration to guarantee the next quality for this recipe.\"\n\nHier zit het hele verhaal, en het is de reden dat mensen hem verkeerd gebruiken. De accu gaat tot |cffffffff1000|r en vult met ongeveer |cffffffff250 per dag|r, dus reken op zo'n vier dagen van leeg naar vol. Dat is traag. Elke keer dat je hem gebruikt, gebruik je een stukje van je komende dagen, en als hij leeg is kun je alleen maar wachten.\n\nElk beroep heeft zijn |cffffffffeigen|r accu. Als alchemist én kruidenplukker heb je er twee, en ze staan los van elkaar.\n\nHij is per keer ook niet goedkoop. Eén echte craft kostte 358 van de 1000 — meer dan een derde van de accu voor één item.\n\nWel doen: iets waar je één rang tekortkomt en dat je zelf gaat dragen of gebruiken; een opdracht met een minimumkwaliteit die je anders niet haalt, want zonder Concentration kun je die opdracht niet eens afmaken; en iets duurs, waar het verschil tussen de rangen meer waard is dan een dag accu.\n\nNiet doen: iets wat je toch al op de hoogste rang maakt, want dan koop je niets en ben je de accu kwijt. Dat is de meest gemaakte fout, omdat mensen het knopje aan laten staan en het niet merken. En goedkope bulk — vijftig drankjes één rang hoger is aardig, maar geen vier dagen waard.\n\nJe krijgt er soms wat van terug. |cffffffffIngenuity|r, een van de zes stats, geeft af en toe een deel terug van wat je net uitgaf, en het spel meldt dat ook. Dat is precies waarom Ingenuity pas interessant wordt zodra je op kwaliteit begint te sturen: zonder uitgaven valt er niets terug te geven.\n\nNog één ding, en dat gaat over mensen in plaats van mechaniek. Zet je Concentration in om de gevraagde kwaliteit te halen op |cffffffffandermans|r opdracht, dan krijgt de besteller het betere item en betaal jij uit een accu die dagen nodig heeft om bij te komen. Ervaren crafters vragen daar meer voor. Dat is geen regel van het spel en er staat geen tarief voor, maar het is goed om te weten dat ernaar vragen niet gierig is, en gevraagd worden niet raar.\n\nConcentration is niet iets wat je moet beheren of optimaliseren. Het is een noodrem, en hij staat er voor het moment dat je één rang tekortkomt op iets wat het waard is. Loopt hij vanzelf vol terwijl je speelt, dan doe je het goed. Staat hij weken op vol, dan laat je waarschijnlijk kwaliteit liggen.",
	PROFACAD_CH_CONC_TASK = "Zoek je Concentration-balk en kijk of hij al weken op vol staat.",
	PROFACAD_CH_GOLD_TITLE = "Goud verdienen zonder jezelf voor de gek te houden",
	PROFACAD_CH_GOLD_INTRO = "Er is maar één som, en bijna niemand maakt hem: wat je ervoor krijgt, min alles wat erin ging, min 5% voor het veilinghuis.",
	PROFACAD_CH_GOLD_BODY = "Het woord dat mensen overslaan is |cffffffffalles|r. Zelfgeplukte kruiden zijn |cffffffffniet gratis|r. Ze hebben een marktprijs, en stop je ze in een drankje in plaats van ze te verkopen, dan heb je die prijs uitgegeven — je betaalt hem alleen aan jezelf. Is het kruid meer waard dan het drankje, dan is craften |cffffffffverlies dat als winst voelt|r.\n\n|cffffcc00Er zijn twee markten, en ze hebben tegengestelde natuurwetten.|r Bijna alle verwarring over of een beroep \"loont\" komt doordat mensen die twee door elkaar halen.\n\nDe eerste is |cffffffffhandelswaar|r: grondstoffen, drankjes, flasks, edelstenen — alles wat stapelt. Je verkoopt spullen, en je concurreert met de hele regio in plaats van met je eigen realm. Kopers zien niets anders dan de prijs.\n\nDe tweede is |cffffffffgemaakte uitrusting|r. Die blijft op je eigen realm, en het beste spul zit aan één persoon vast en kan dus helemaal niet op de veiling. Daar verkoop je geen spullen maar je vakmanschap.\n\n|cffffcc00Waarom de handelswaar-markt altijd naar de bodem zakt|r is het begrijpen waard, en geen van de redenen is \"er zijn veel spelers\". Het spel pakt automatisch de goedkoopste aanbieding, dus één koperstuk boven de laagste prijs betekent geen verkoop. Je concurreert met alle realms in je regio tegelijk. Multicraft deelt gratis extra aanbod uit, en werkt alleen op dingen die stapelen — precies deze markt. En verbruiksartikelen hebben maar twee kwaliteitsrangen in plaats van de hele ladder, dus het is een kortere val.\n\nEr is één rem: zolang crafters Concentration nodig hebben om de hoogste rang te halen, is topkwaliteit schaars. Zodra ze het op eigen kracht halen laat die rem los en zakt de prijs. In deze markt verdien je dus in het venster |cffffffffvóórdat|r dat gebeurt.\n\n|cffffcc00Wat een prijs wél beschermt is een slot op het aanbod.|r Er zijn vier soorten: een cooldown op het recept, een grondstof die de maker nooit zelf kan leveren, een recept achter reputatie, en Concentration, omdat die maar langzaam bijvult. |cffffffffWaar een slot zit, zit marge. Waar geen slot zit, zit volume en bijna geen marge.|r Dat is het hele onderwerp in één zin.\n\nVerzamelen is de uitzondering die het bewijst: wat je plukt heeft geen kostprijs, dus je |cffffffffkunt|r niet verliezen — de enige manier van goud verdienen waarbij een beginner geen fout kan maken. Maar geen kostprijs betekent ook geen drempel, dus de prijs zakt naar wat de minst kieskeurige verzamelaar accepteert.\n\n|cffffcc00Elk gemaakt item valt in één van drie bakjes, en het derde is de valkuil.|r Vrij verhandelbaar zegt het zelf in het tekstblokje: \"Can be bought and sold on the Auction House.\" Soulbound kan niet op de veiling maar |cffffffffwél|r via een bestelling, want die levert rechtstreeks in het postvak van de klant — daar verkoop je arbeid, geen product. En |cffffffffBinds to Warband|r kan geen van beide: geen veiling, geen bestelling, alleen jij en je eigen alts. Dat is geen verdienmodel, dat is een dienst.\n\nAlchemisten in het bijzonder: de twee kookpotten waarmee je je hele raid van drankjes voorziet zijn |cffffffffallebei|r Binds to Warband. Je kunt ze nooit verkopen. Je maakt ze, je neemt ze mee, en wat je terugkrijgt is goodwill. Dat is prima — maar het hoort een keuze te zijn en geen ontdekking achteraf, want er gaan dure grondstoffen in.\n\n|cffffcc00Bulk of op bestelling?|r In bulk verkoop je het product, concurreer je met de hele regio op prijs, is je volume onbeperkt en wordt je marge steeds dunner. Op bestelling verkoop je je kunde, concurreer je met crafters op je eigen realm op reputatie, is je volume begrensd en je marge stabieler. Daaruit volgt een rekensom en geen mening: |cffffffffde openbare bestelwachtrij is geen bedrijf|r. Je hebt er vier tegoed en er komt er één per dag bij — ongeveer zeven per week. Dat is een bijverdienste. |cffffffffPersoonlijke en gilde-bestellingen zijn onbeperkt|r, dus een handvol vaste klanten die jou rechtstreeks een bestelling sturen is waar het echte werk zit.\n\n|cffffcc00De grootste beginnersfout|r is craften voordat je hebt gekeken wat de grondstoffen kosten. Hij heeft twee gezichten en het is dezelfde fout: \"ik heb het zelf geplukt, dus het is gratis\" en \"ik heb dit recept, dus ik ga het maken\". Een recept hebben zegt niets over of het loont. |cffffffffKijk eerst wat het kost. Dan pas of je het maakt.|r\n\nEn wantrouw elk \"X goud per uur\" uit een gids of video: dat verschilt per realm en is meestal verzonnen. Meet het op je eigen realm. Auctionator laat zien wat dingen echt kosten; CraftSim rekent per recept uit wat een craft oplevert tegen de actuele materiaalprijzen, en is verreweg het nuttigste dat je kunt installeren als je serieus wil verdienen.",
	PROFACAD_CH_GOLD_DATED_202608 = "|cffffcc00Hoe het ervoor staat, eind augustus 2026 — en deze helft verloopt.|r Season 2 is een paar dagen oud, dus lees het hieronder als een momentopname en niet als een regel. Goed om te weten: vrijwel elke \"Season 2\"-gids die er is draagt een datum van vóór de seizoensstart, wat hun uitspraken tot voorspellingen maakt in plaats van waarnemingen. Er bestaat van niemand een gepubliceerde prijsreeks van deze eerste weken.\n\n|cffffffffAlchemy.|r Drankjes en flasks zijn vrij verhandelbaar en verkopen nu goed — de raid is net open en de vraag piekt. Maar dit is de handelswaar-markt in volle glorie, dus reken erop dat de marge zakt naarmate meer crafters de hoogste rang zonder Concentration halen. Wondrous Synergist is je stabielere inkomen: het heeft een cooldown van ongeveer een dag, dus niemand kan de markt overspoelen — precies het slot van hierboven — en het voedt beide kookpotten en de epische steen. Housing-decoratie is de onderschatte optie: zes recepten, verhandelbaar, en het stapelt niet, dus het concurreert op je eigen realm in plaats van in de regionale poel. Eén marktverhaal om mee te nemen: het nieuwe gezondheidsdrankje van 12.1 verbruikt 25 van het oude, dus dat oude is van eindproduct naar ingrediënt gepromoveerd en als eindproduct ongeveer gehalveerd in waarde. Wie er in juli een voorraad van aanlegde, keek op 11 augustus tegen die halvering aan.\n\n|cffffffffHerbalism.|r Nocturnal Lotus is het dure kruid, en het waarom is precies aanwijsbaar: het is het enige Midnight-kruid van zeldzame kwaliteit, het heeft geen eigen vindplaats (het is bijvangst bij elk ander kruid), en het zit in alle vier de flasks en beide kookpotten — elf recepten in totaal. De twee nieuwe materialen van The Coiled Isle zijn allebei verhandelbaar, met één waarschuwing: ze zijn |cffffffffniet|r exclusief voor kruidenplukkers. Mijnwerkers halen ze uit hun eigen vindplaatsen, en één ervan valt ook van dieren via Skinning. Meerdere gidsen suggereren het tegendeel.",
	PROFACAD_CH_GOLD_TASK = "Kijk vóór je volgende craft op wat de grondstoffen kosten — en besluit daarna pas of je het maakt.",
	PROFACAD_CH_RECIPES_TITLE = "Waar komen recepten vandaan?",
	PROFACAD_CH_RECIPES_INTRO = "Niet weten waar recepten vandaan komen is de meest voorkomende reden dat een professie vastloopt. Er zijn vijf bronnen, en maar één daarvan is je trainer.",
	PROFACAD_CH_RECIPES_BODY = "Recepten komen uit vijf bronnen: je trainer (kopen tijdens het skill-levelen), je specialisatie-trees (unlocken als je KP uitgeeft), Moxie-vendors (volgend hoofdstuk), renown-beloningen en wereld-drops of schatten.\n\nVuistregel: craft elk nieuw recept minstens één keer. Elke first craft geeft +1 KP en 10x Moxie — ook als je het resultaat bij de vendor dumpt.\n\nNoemt een gids een recept dat jij niet hebt? Check eerst waar het vandaan komt voor je gaat farmen.",
	PROFACAD_CH_RECIPES_TASK = "Leer één nieuw recept en craft het één keer (first craft = +1 KP + Moxie).",
	PROFACAD_CH_MOXIE_TITLE = "Moxie, je boodschappengeld",
	PROFACAD_CH_MOXIE_INTRO = "Elke professie heeft een eigen valuta, en die koopt alleen spullen voor díe professie. Handig om te weten voordat je met de verkeerde gaat winkelen.",
	PROFACAD_CH_MOXIE_BODY = "Artisan's Moxie is een professie-specifieke valuta: je Enchanting-Moxie koopt alleen Enchanting-spullen. Je verdient grofweg 5x Moxie per KP, en 10x bij first crafts.\n\nGeef het uit bij de professie-vendors in Silvermoon aan nieuwe recepten, zakken materialen en boeken die bonus-KP geven.\n\nTip: blijf niet eindeloos sparen — vroege recepten en de KP-boeken zijn de beste waarde.",
	PROFACAD_CH_MOXIE_TASK = "Zoek je Moxie op in de currency-tab en check je saldo.",
	PROFACAD_CH_WEEKLY_TITLE = "Je wekelijkse routine",
	PROFACAD_CH_WEEKLY_INTRO = "De meeste Knowledge komt elke week terug — een gemiste week is dus definitief weg. Dit is de routine waar je een gewoonte van wilt maken.",
	PROFACAD_CH_WEEKLY_BODY = "De meeste KP komt uit herhaalbare wekelijkse bronnen. De basis voor elke professie:\n\n1. Trainer-weekly — unlockt na de intro-quest bij Captain Flaresworn (Work Order-station, Silvermoon Bazaar). Enchanting vereist eerst skill 25.\n2. Twee willekeurige treasure-drop-items uit containers in de open wereld (+2 KP elk).\n3. Een Thalassian Treatise (+1 KP) — gemaakt door Inscription; warbound, dus een alt of een work order regelt er één.\n4. Darkmoon Faire-week: +3 KP en +15 Moxie, maandelijks.\n\nWeek gemist? Het inhaalsysteem geeft gemiste KP langzaam terug — nadat je de huidige weeklies hebt gedaan.",
	PROFACAD_CH_WEEKLY_TASK = "Pak de intro-quest bij Captain Flaresworn en doe je eerste trainer-weekly.",
	PROFACAD_CH_WORKORDERS_TITLE = "Work orders: het vakmanschap van een ander kopen",
	PROFACAD_CH_WORKORDERS_INTRO = "Op het veilinghuis koop je spullen die al gemaakt zijn. Bij de order-tafel werkt het andersom: jij brengt de grondstoffen en betaalt iemand voor het werk.",
	PROFACAD_CH_WORKORDERS_ADVANCED = "Twee dingen waardoor het systeem kapot lijkt terwijl het dat niet is. Aan je eigen werkbank blijft de lijst met openbare bestellingen leeg tot je op |cffffffffSearch|r drukt — er is niets mis, hij laadt gewoon niet vanzelf. En de man die bij de order-tafel staat, Captain Flaresworn, hoort hier helemaal niet bij: die geeft je de startquest voor je beroep, je weekopdrachten en gratis zakjes materiaal. Nuttig, maar niet waarvoor je komt.",
	PROFACAD_CH_WORKORDERS_BODY = "Dat werkt zo omdat de beste gemaakte uitrusting aan één persoon vastzit zodra hij bestaat. Niemand kan hem vooraf maken en in de winkel leggen, dus iemand moet hem |cffffffffspeciaal voor jou|r maken.\n\n|cffffcc00Er zijn twee balies, en dat is waar het meestal misgaat.|r Wil je iets laten maken, ga dan naar de order-tafel in de Bazaar in Silvermoon — de grote gouden hamer op je minimap. De vrouw die je nodig hebt heet Mar'nah. Wil je zelf iets voor een ander maken, ga dan naar de |cffffffffwerkbank van je eigen beroep|r. Sta je daar niet vlak naast, dan is er geen knop en geen lijst, en lijkt het alsof het systeem niet bestaat. Dat is de meest gemaakte fout, en het spel legt het nergens uit.\n\n|cffffcc00Iets laten maken.|r Kies je item, en kies dan aan wie je het vraagt. Aan niemand in het bijzonder (de knop heet Public Order): iedereen op jouw realm ziet je bestelling en de eerste die hem oppakt maakt hem. Snel, maar je krijgt wat je krijgt — |cffffffffje kunt hier geen kwaliteit eisen|r, en je moet alle grondstoffen zelf meesturen. Aan één bepaalde speler (Personal Order): daar mag je wél een minimumkwaliteit eisen, en mag je afspreken dat hij zelf materiaal bijlegt. Aan je hele gilde (Guild Order) werkt hetzelfde en bereikt ook gildegenoten op andere realms. Je stelt zelf in wat je betaalt, en een knopje ernaast laat zien wat anderen recent voor hetzelfde item betaalden.\n\nDrie dingen om te weten voor je op bestellen klikt. Sommige speciale grondstoffen kan de maker nooit voor je regelen, die stuur je altijd zelf mee. Materiaal in je Warband bank |cfffffffftelt niet mee|r — leg het in je tassen. En het item wordt van |cffffffffjou|r, dus bestel op het personage dat het gaat dragen, niet op degene die toevallig het geld heeft. Zodra iemand je bestelling oppakt kun je hem niet meer intrekken; het item komt daarna met de post.\n\n|cffffcc00Zelf iets voor een ander maken.|r Aan je werkbank zie je vóór je begint precies wat je eraan overhoudt. Klik je op starten, dan heb je |cffffffff30 minuten|r om het af te maken — genoeg om nog even wat te halen, niet genoeg om te gaan eten.\n\nJe kunt niet eindeloos openbare bestellingen aannemen: je hebt er |cffffffffvier tegoed|r, en er |cffffffffkomt er elke dag één bij|r. Dus ongeveer zeven per week, niet vier per dag. Bestellingen die bijna verlopen zijn mag je gratis oppakken.\n\nKun je een bestelling niet aannemen, dan is het een van deze vier: je kent het recept niet, je specialisatie is nog niet ver genoeg voor de extra's die gevraagd worden, er wordt een kwaliteit gevraagd die jij niet haalt, of je tegoed is op.\n\nEn één ding dat je stilletjes geld kost: |cffffffffkijk wiens grondstoffen je gebruikt.|r Bij openbare bestellingen levert de besteller altijd alles, maar bij de andere soorten mag hij ook niets meesturen — en dan craft jij vrolijk met je eigen dure spullen voor een fooi.",
	PROFACAD_CH_WORKORDERS_TASK = "Zoek de order-tafel in de Silvermoon Bazaar, en zoek daarna de werkbank van je eigen beroep. Dat is niet dezelfde plek.",
	PROFACAD_CH_PATRON_TITLE = "Patron orders, je wekelijkse kennismotor",
	PROFACAD_CH_PATRON_INTRO = "De vierde soort bestelling komt van het spel zelf in plaats van van een speler, en het is degene die de meeste mensen nooit vinden.",
	PROFACAD_CH_PATRON_BODY = "Aan je eigen werkbank staat een tabblad |cffffffffPatron|r waar het spel zelf je bestellingen geeft. Geen andere speler, geen concurrentie — ze zijn alleen voor jou. Je betaling is niet zozeer goud, maar |cffffffffKnowledge Points|r: dezelfde punten waarmee je je beroep sterker maakt.\n\nDit is veruit je grootste wekelijkse bron ervan. Wie ze overslaat blijft achter en snapt niet waarom anderen sneller gaan.\n\nEr komt om de paar dagen een nieuwe lading. Elke bestelling vraagt een bepaalde kwaliteit, en soms moet je zelf materiaal bijleggen — kijk dat na, want een dure bestelling voor twee punten is het niet altijd waard. Overslaan mag.\n\n|cffffcc00En dan de valstrik.|r Het spel geeft je elke dag een kleine bestelling van één punt erbij, maar |cffffffffalleen zolang je achterloopt op je weekdoel|r. Doe je maandag meteen alle grote bestellingen, dan ben je bij — en stoppen die dagelijkse kleintjes voor de rest van de week.\n\nDus: |cfffffffflaat de grote bestellingen staan tot ze bijna verlopen|r. Dan blijf je ondertussen de kleintjes krijgen, en heb je aan het eind van de week meer punten. Het voelt verkeerd. Het is toch zo.",
	PROFACAD_CH_PATRON_TASK = "Open het Patron-tabblad aan je eigen werkbank en kijk wat deze week te bieden heeft.",
	PROFACAD_CH_ENCHANTING_TITLE = "Enchanting-startgids",
	PROFACAD_CH_ENCHANTING_INTRO = "Enchanting zet permanente stats op je gear, en het is de enige professie die ongewenste loot omzet in vooruitgang. Disenchanten betekent simpelweg een groen of blauw item slopen voor materialen. Je eerste stap: disenchant de troep in je tas. De build-volgorde hieronder is voor als je het onder de knie hebt.",
	PROFACAD_CH_ENCHANTING_ADVANCED = "Voorbij de starter build? Zodra die drie roots staan is er geen enkele juiste volgende node - het hangt af van wat je met de professie wilt. Punten in de Weapon/Ring/Chest-tak leveren de enchants waar mensen echt om vragen. Punten in Disenchanting Delegate betekenen dat je minder materiaal hoeft te kopen. Punten in Spellbound Shatterer verhogen je EIGEN craft-stats: elk +1 Ingenuity, en vijf ervan openen één subtak met +1 Resourcefulness, Ingenuity of Multicraft per punt. Lees die drie voor je kiest: Resourcefulness geeft 5% meer materiaal terug en Ingenuity 5% meer Concentration op alles wat je maakt, terwijl de Multicraft-bonus alleen voor illusions geldt. De Shatter Essence-buff zelf is een vaste +5 op elk en groeit NIET mee met punten. Wat je ook kiest: geef ze uit. Onbestede Knowledge doet helemaal niets, en geen van deze keuzes is fout genoeg om punten voor te bewaren.",
	PROFACAD_CH_ENCHANTING_BODY = "Enchanting is de vreemde eend: je verdient de meeste wekelijkse KP door gear te disenchanten. Elke week geven de eerste 5 Swirling Arcane Essences +1 KP per stuk, daarna geeft een Brimming Mana Shard +4 — dat is +9 KP per week, puur voor het versplinteren van loot. Enchanting krijgt geen patron orders.\n\nStartbuild: eerst Disenchanting Delegate — dat is de boom waar de rest van het beroep op draait, en het is waar de twee best onderhouden guides allebei beginnen. Dan Elevating Equipment — root tot ~30, daarna de Weapon/Chest/Ring-tak van één familie: Skill bepaalt welke kwaliteitsrang je haalt, en een top-enchant die je niet kúnt maken verkoop je ook niet. Spellbound Shatterer als laatste — zijn stats verlagen wat een craft kost, en dat betaalt zich pas als je de goede versie überhaupt kunt maken.\n\nExtra KP-boeken: Silvermoon Court renown 6, en de Abundance-event-vendor (Chel the Chip) verkoopt ook een Enchanting-boek.",
	PROFACAD_CH_ENCHANTING_FAMILIES = "|cffe8c36aDe drie families, en waarom de keuze uitmaakt|r|nMidnight-enchanting bestaat uit drie families — Amani, Thalassian en Haranir — en elk heeft dezelfde drie takken: Weapon/Chest/Ring, Helm/Shoulder/Boot, en Profession Tool.|n|nZe zijn even sterk. In de data van het spel zelf is elke gear-enchant item level 120, en de schaalgetallen zijn tussen de families identiek waar de stat hetzelfde is. Er is dus geen beste, en geen enkele is verouderd.|n|nWat wél verschilt is welke stats je mag verkopen:|n• |cffffffffRing|r — Mastery (Amani), Crit (Haranir), Haste en Versatility (Thalassian).|n• |cffffffffChest|r — Strength (Amani), Agility (Haranir), Intellect (Thalassian). Haranir heeft daarnaast |cffffffffMark of the Worldsoul|r, die bij elke klasse past en ongeveer 25% meer primary stat geeft dan de andere drie — de enige plek waar een familie duidelijk vóór ligt.|n• |cffffffffHelm, shoulders, boots|r — Speed, Leech en Avoidance komen in elke familie één keer voor, steeds in een ander slot. Leech op shoulders bestaat alleen bij Thalassian.|n• |cffffffffProfession tools|r — Perception en Resourcefulness (Amani), Finesse en Multicraft (Haranir), Deftness en Ingenuity (Thalassian). Geen enkele overlap.|n|nDe tak die je neemt bepaalt dus welke familie je naar de hoogste kwaliteitsrang kunt duwen: hij geeft +5 Skill voor die familie en laat je Finishing Reagents op haar recepten gebruiken. Het is géén receptenlijst — de lagere enchants leer je vanzelf tijdens het levelen, en een deel van de hogere komt uit formules die je koopt of vindt. En binnen een familie is de ring-stat nooit de wapen-stat: Mastery-ringen zijn Amani, maar de Mastery-proc op wapens is Thalassian.|n|nTwee dingen waar mensen op stuklopen: er bestaan helemaal géén Midnight-enchants voor cloak, bracers, belt of gloves, en Midnight heeft twee kwaliteitstiers waar de vorige uitbreiding er drie had.|n|n|cffffd100Wat we niet weten:|r wat dit allemaal opbrengt. De data van het spel zegt daar niets over en we hebben geen betrouwbare marktbron. Kijk zelf even op je auction house voor je 20 punten vastlegt. De takken schermen wél recepten af: het spel noemt Silvermoon's Alacrity als afkomstig uit Elevating Equipment - Silvermoon's Spellpower, terwijl zijn broertje Silvermoon's Tenacity bij een vendor in Eversong Woods ligt. Allebei de routes bestaan, en |cffffffff/mh unlearned|r zegt per ontbrekend recept welke van de twee het is.",
	PROFACAD_CH_ENCHANTING_TASK = "Disenchant gear tot je deze week je 5 Essences + Mana Shard hebt (+9 KP).",
	PROFACAD_CH_ALCHEMY_TITLE = "Alchemy-startgids",
	PROFACAD_CH_ALCHEMY_INTRO = "Alchemy maakt de potions en flasks die iedereen vóór een boss drinkt, dus er is altijd vraag. Je eerste stap is gewoon blijven brouwen terwijl je skill oploopt.",
	PROFACAD_CH_ALCHEMY_BODY = "Alchemy biedt je een tree op skill 25, 50, 60 en 75 — het spel kiest niet, dat doe jij. De vier zijn Potion Prowess (drankjes, met een Light- en een Void-kant), Fluent in Flasks, Transmutation Authority en Alchemical Mastery.\n\n|cffffcc00Starter build, in deze volgorde.|r Eerst |cffffffffPotion Prowess|r: vol geeft hij de Voidlight Potion Cauldron, en die dient je goud én je gilde tegelijk. Daarna |cffffffffPath of Light|r en |cffffffffProlific Potioneer - Light|r, de Multicraft-node — Light omdat dat het drankje is dat dit seizoen verkoopt. Dan |cffffffffAlchemical Mastery|r en daarbinnen |cffffffffReuse|r, die je kruiden teruggeeft en sterk is als je ze ook zelf plukt.\n\nDaarna ongeveer 15 punten in |cffffffffFluent in Flasks|r, waarmee je eigen flasks twee keer zo lang meegaan, en dan |cffffffffSin'dorei Specialist|r. |cffffffffTransmutation Authority|r komt als laatste, niet als tweede.\n\n|cffffffffHaranir Secrets is geen bijzaak.|r Zijn eigen tooltip eindigt met \"and Cauldron of Sin'dorei Flasks\" — zonder punten daar haal je de flask-ketel niet op de hoogste rang. Gidsen parafraseren die node als \"phials only\" en laten precies die halve zin weg.",
	PROFACAD_CH_ALCHEMY_TASK = "Doe deze week je beschikbare Patron Orders (crafting-order-bord).",
	PROFACAD_CH_TAILORING_TITLE = "Tailoring-startgids",
	PROFACAD_CH_TAILORING_INTRO = "Draag je cloth, dan maakt tailoring je eigen gear — én de stof die elke andere crafter nodig heeft. Je eerste stap: het textiel oppakken waar je nu langsloopt.",
	PROFACAD_CH_TAILORING_BODY = "Tailors zijn de enige bron van gemaakte cloth armor — én van de bolts (Arcanoweave en Sunfire Silk) waar bags, embellished gear en spellthreads op draaien. Die bolts zitten achter een dagelijkse cooldown die alleen gespecialiseerde tailors unlocken: reden genoeg om bewust te speccen.\n\nStarter build: zet je eerste ~30 punten in de Nimble Needlework-root (skill en stats voor armor én bolts) en kies dan je focus. Armor: Sin'dorei Finery — kies ÉÉN slot-groep (bijv. robes/trousers/cloaks) en maak die af voor je aan de volgende begint. Bolts/goud: Sunfire Silk Weaving of Arcanoweaving plus de Expertise-node (meer bolts, kortere cooldown).\n\nFiber Arts en Fabric Specialist verbeteren elke craft (en je cloth-drops in specifieke zones) — prima voor losse punten.",
	PROFACAD_CH_TAILORING_TASK = "Unlock een bolt via Nimble Needlework en craft vandaag je bolt-cooldown.",
	PROFACAD_CH_LEATHERWORKING_TITLE = "Leatherworking-startgids",
	PROFACAD_CH_LEATHERWORKING_INTRO = "Leatherworking dekt twee soorten armor tegelijk, vandaar twee bomen. Bepaal vroeg welke je zelf draagt, zodat je Knowledge naar de goede kant gaat.",
	PROFACAD_CH_LEATHERWORKING_BODY = "Leatherworkers zijn de enige bron van zowel gemaakte leather- als mail-gear — twee aparte trees, dus kies eerst één armor-type. Learned Leatherworker is de fundamentals-tree en verlaagt zelfs je Concentration-kosten per craft.\n\nStarter build: eerst Lasting Leather (leather) ÓF Safeguarding Scales (mail), en max één slot-subnode tegelijk, daarna Learned Leatherworker. Flawless Fortes komt later: professie-tools aan de ene kant, consumables (armor kits, drums) aan de andere — die verkopen gestaag.",
	PROFACAD_CH_LEATHERWORKING_TASK = "Kies leather of mail en max je eerste slot-subnode.",
	PROFACAD_CH_BLACKSMITHING_TITLE = "Blacksmithing-startgids",
	PROFACAD_CH_BLACKSMITHING_INTRO = "Plate-dragers halen hier hun gear, en de rest komt voor stenen en gereedschap. Je eerste stap: skillen op de goedkope items vóór je Knowledge uitgeeft.",
	PROFACAD_CH_BLACKSMITHING_BODY = "Blacksmiths zijn de enige bron van gemaakte plate gear, plus weaponstones, tool stones en alloys. The Old Ways is je fundamentals-tree (Ingenuity, Multicraft, Resourcefulness voor ÁLLE crafts) — vul die naast wat je ook kiest.\n\nKies daarna een focus: Armorsmithing (per slot-groep) of Weaponsmithing (per wapentype) — max ÉÉN subnode volledig voor je aan de volgende begint. Craftsmithing maakt professie-gereedschap voor zes andere professies. Alloys, weaponstones en tool stones verkopen prima zonder crafting orders.",
	PROFACAD_CH_BLACKSMITHING_TASK = "Kies je focus-tree (Armorsmithing of Weaponsmithing) en max eerst één subnode.",
	PROFACAD_CH_ENGINEERING_TITLE = "Engineering-startgids",
	PROFACAD_CH_ENGINEERING_INTRO = "Engineering is de eigenzinnige, leuke: gadgets, guns en goggles die alleen jij kunt dragen. Verwacht meer bruikbaarheid en gekkigheid dan pure kracht.",
	PROFACAD_CH_ENGINEERING_BODY = "Engineers zijn de enige bron van guns en maken goggles (alleen voor engineers), bracers en boots — plus gadgets en scopes. Recycling is de fundamentals-tree: skill op ÁLLE crafts, en je krijgt materialen terug tijdens het werken.\n\nNa Recycling: kies één tree en max eerst één node. Let op: in Bits and Bots misleiden de namen — Bits is reagents/cogwheels (scopes), Bots is optionele reagents en gadgets. Scopes, boot-attachments en gadgets verkopen betrouwbaar op het veilinghuis.",
	PROFACAD_CH_ENGINEERING_TASK = "Zet je eerste punten in Recycling en kies daarna je focus-tree.",
	PROFACAD_CH_INSCRIPTION_TITLE = "Inscription-startgids",
	PROFACAD_CH_INSCRIPTION_INTRO = "Inscription is de stille kracht: veel van wat scribes maken belandt in de crafts van anderen in plaats van in hun eigen tas, en juist daarom is er gestaag vraag naar.",
	PROFACAD_CH_INSCRIPTION_BODY = "Scribes maken staves, bows, off-hands, missives (stats op crafted gear), Vantus-runes en Darkmoon-kaarten. Uniek voordeel: de centrale Calm Hands-node maxen unlockt de wekelijkse Thalassian Treatise — +2 KP per week, als enige professie.\n\nDus: altijd eerst Calm Hands. Daarna Blueprints (gear), Perfected Products (consumables) of Darkmoon Curiosity (kaarten, per kaarttype). Vantus-runes, missives en inkten verkopen gestaag.",
	PROFACAD_CH_INSCRIPTION_TASK = "Werk naar het maxen van de centrale Calm Hands-node (wekelijkse Treatise = +2 KP/week).",
	PROFACAD_CH_JEWELCRAFTING_TITLE = "Jewelcrafting-startgids",
	PROFACAD_CH_JEWELCRAFTING_INTRO = "Ringen en kettingen zijn twee slots die niemand anders kan maken, dus jewelcrafters zitten nooit zonder klanten.",
	PROFACAD_CH_JEWELCRAFTING_BODY = "Jewelcrafters zijn de enige bron van gemaakte ringen en kettingen — en die heeft iedereen nodig. Prospecting maakt gems van erts; crushing maakt Gemdust van overtollige gems. Tip: besteed nooit Concentration aan prospecting of crushing.\n\nBegin met Thoughtful Throughput (fundamentals) en onthoud twee shortcuts: alleen de centrale Glamorous Gems-node is nodig om Eversong Diamonds op max kwaliteit te slijpen, en Proficient Processor (prospecting/crushing) is goedkoop compleet te maken. Geslepen gems en reagents zoals Sunglass Vial verkopen goed.",
	PROFACAD_CH_JEWELCRAFTING_TASK = "Unlock de centrale Glamorous Gems-node en slijp je eerste kwaliteits-gem.",
	PROFACAD_CH_HERBALISM_TITLE = "Herbalism-startgids",
	PROFACAD_CH_HERBALISM_INTRO = "Gatheren is de rustigste manier om professies binnen te komen: geen recepten zoeken, geen boom vooraf plannen, gewoon dingen oppakken. De upgrade die iedereen wil is verzamelen zonder af te stijgen.",
	PROFACAD_CH_HERBALISM_BODY = "Elk kruid komt in elk gebied voor, dus over waar je moet plukken hoef je niet na te denken. De volgorde hieronder is wat de route in deze addon nu adviseert, en elke stap is één ding dat je ontgrendelt in plaats van een vage verdeling.\n\n|cffffcc00Eerst: ongeveer 40 punten in Botany.|r Dat is plukken vanaf je rijdier, en dat is veruit de grootste tijdwinst van het beroep — zonder dat stap je bij elke plant af en weer op. Druids slaan dit over: die plukken al vanaf hun rijdier.\n\n|cffffcc00Dan ongeveer 20 in Mulching|r, die mensen overslaan en die dat niet verdient. Hij geeft je Imbued Mulch: een gegarandeerde zeldzame vondst bij je volgende pluk, en die zeldzame vondst is Nocturnal Lotus — het enige Midnight-kruid van zeldzame kwaliteit, zonder eigen vindplaats, en het zit in alle vier de flasks en beide ketels.\n\n|cffffcc00Daarna Bountiful Harvests|r voor de lange termijn: meer kruiden per vindplaats en meer vaardigheid, dus vaker topkwaliteit. Daarbinnen heeft elk kruid een eigen node, dus je kunt mikken op wat op jouw realm het best verkoopt.\n\n|cffffcc00Laat Midnight Overload links liggen.|r Hij werkt alleen bij de elementale vindplaatsen, kost veel punten, en die kom je te weinig tegen. Alleen zinvol als je gericht motes farmt.\n\nDie puntenaantallen komen elk uit één bron. Hang in het spel boven de node voor je klikt — de tooltip heeft het echte getal, en je krijgt maar één reset.",
	PROFACAD_CH_HERBALISM_TASK = "Unlock mounted gatheren via de Botany-root (als Druid overslaan).",
	PROFACAD_CH_MINING_TITLE = "Mining-startgids",
	PROFACAD_CH_MINING_INTRO = "Mining voedt blacksmithing, jewelcrafting en engineering, dus het verdient ook als je zelf nooit iets maakt. Eerste doel: verzamelen zonder af te stijgen.",
	PROFACAD_CH_MINING_BODY = "Alle ertsen komen in alle zones voor. Eerst: open de Over-LODED-tak en stop daar — het ontgrendelen geeft je de Overload-ability en zijn cooldown-reductie al, dus die ene stap verdient zichzelf terug en meer is niet nodig. Daarna ~40 punten in de Meticulous Mining-root om vanaf je mount te minen — dé quality-of-life-unlock van Midnight. Daarna ~50 in de Plentiful Ores-root voor skill op elk erts.\n\nVul daarna losse erts-nodes (gelijkmatig verdelen, tenzij één erts veel duurder is); een erts maxen verhoogt Dazzling Thorium-drops ervan. Speciale infused deposits (Lightfused, Wild, Primal, Voidbound) kun je Overloaden voor een berg motes — de eerste keer per ertssoort +1 Knowledge Point. De 12-uurs-cooldown zakt ±30 minuten per node die je mined en 40 root-punten geven een tweede charge. Meer punten in Over-LODED verhogen de opbrengst, maar dat is een gok op wat motes opleveren — daarom opent de bouwvolgorde hem en gaat verder. Refulgent Copper is constant gevraagd.",
	PROFACAD_CH_MINING_TASK = "Unlock mounted minen via de Meticulous Mining-root.",
	PROFACAD_CH_SKINNING_TITLE = "Skinning-startgids",
	PROFACAD_CH_SKINNING_INTRO = "Skinning maakt materiaal van wat je toch al doodmaakt. Het past natuurlijk bij leatherworking, maar verdient prima op zichzelf.",
	PROFACAD_CH_SKINNING_BODY = "Skinners voeden de leatherworkers — en Midnight geeft je er gereedschap voor: high-value beasts staan op je minimap, Diffusers trekken motes uit mobs, en Majestic Lures (Talented Tracker) roepen één keer per dag een zone-beest op dat epische materialen dropt.\n\nStarter build (farmen): een paar punten in de Thorough Tanning-root, dan de leather- of scales-tak maxen, dan terug de root in. Daarna Gainful Gathering: Careful Carving (Finesse, massa-farmen) of Trophy Taker (Perception, rares). Wissel je tools mee: Finesse voor volume, Perception voor rares.",
	PROFACAD_CH_SKINNING_TASK = "Max de leather- of scales-tak in Thorough Tanning en skin met de passende tool.",
	TAB_DELVE_LOG = "Delve & Ritual Log",
	DELVELOG_SUBTITLE = "Een logboek per personage van elke Midnight-delve én ritual-run die je afrondt: tier, tijd, deaths en (bij delves) gebruikte sleutel en de eindbaas. Wordt automatisch bijgehouden — je hoeft dit niet open te hebben.",
	DELVELOG_EMPTY = "Nog geen delve-runs vastgelegd. Rond een Midnight-delve af om te beginnen met bijhouden.",
	DELVELOG_SEC_RITUALS = "Rituals",
