	ACADEMY_SUBTITLE = "Korte masterclass voor tanken, healen en DPS in groups - mindset, prep-vinkjes en een rustige opbouw naar dungeons. Geen parse-guide.",
	ACADEMY_TRACK_TANK = "Tank-track",
	ACADEMY_TRACK_HEAL = "Heal-track",
	ACADEMY_TRACK_DPS = "DPS-track",
	ACADEMY_CLASS_FMT = "Ingelogd: %s - %s (open Macro's / Consumables / Guides via de zijbalk)",
	ACADEMY_CLASS_OPEN_CHAT_FMT = "Macro's geopend voor %s - %s. Check ook Consumables voor flasks en pots.",

	ACADEMY_PREF_TITLE = "Pre-flight checklist (vink als klaar)",
	ACADEMY_PREF_HINT = "Vinkjes worden opgeslagen. Open de juiste tab via de zijbalk als je voorbereidt.",
	ACADEMY_PREF_TANK_INTERRUPT = "Interrupt-macro op mijn bar (Macros-tab)",
	ACADEMY_PREF_TANK_DEFENSIVE = "Een defensive klaar (Guides -> Defensives of In groups-tab)",
	ACADEMY_PREF_TANK_CONSUMABLES = "Flask / pot klaar (Consumables-tab)",
	ACADEMY_PREF_TANK_TAUNT = "Ik ken mijn taunt-toets (1x dummy test)",
	ACADEMY_PREF_HEAL_MACROS = "Mouseover / focus heal macro's (Macros-tab)",
	ACADEMY_PREF_HEAL_DEFENSIVE = "Eigen defensive op bar (Guides -> Defensives of In groups)",
	ACADEMY_PREF_HEAL_CONSUMABLES = "Mana pot / flask (Consumables-tab)",
	ACADEMY_PREF_HEAL_PRACTICE = "1x hover-heal op vriend geoefend",
	ACADEMY_PREF_DPS_ROTATION = "Hoofd-abilities op makkelijk bereikbare toetsen",
	ACADEMY_PREF_DPS_COOLDOWNS = "Damage-cooldowns keybound (niet kwijt op de bar)",
	ACADEMY_PREF_DPS_DEFENSIVE = "Een eigen defensive op mijn bar",
	ACADEMY_PREF_DPS_INTERRUPT = "Mijn interrupt keybound (1x dummy test)",

	ACADEMY_TANK_INTRO_TITLE = "Tank-mindset",
	ACADEMY_TANK_INTRO_BODY = "Jouw taak is tempo en aandacht - niet topping damage meters.\n\nEén rustige pull is beter dan een perfecte rotation op een dode group. Zeg pulls hardop als dat helpt: \"pull over 3\".",
	ACADEMY_TANK_PULL_TITLE = "Tijdens een pull (eerste 10 seconden)",
	ACADEMY_TANK_PULL_BODY = "1. Pak de pack (taunt / threat).\n2. Draai vijanden van de group af waar mogelijk.\n3. Gebruik één defensive bij een damage spike - bewaar de tweede voor \"help\".\n4. Interrupt de gevaarlijke cast (vaak heal of grote hit).\n\nJe hoeft niet meteen elke ability te spammen.",
	ACADEMY_TANK_WIPE_TITLE = "Als het misgaat",
	ACADEMY_TANK_WIPE_BODY = "Een wipe is informatie, geen oordeel. Vraag: \"Was ik te ver vooruit?\" of \"Had ik een defensive bewaard?\"\n\nRepair, eten, opnieuw.",
	ACADEMY_TANK_DUNGEON_TITLE = "Je eerste dungeon (normal)",
	ACADEMY_TANK_DUNGEON_BODY = "Start normal met vrienden of guildies. Rustige pulls - twee kleine packs zijn beter dan één enorme chain.\n\nLet op mana van de healer; pauze tussen pulls. Vraag gerust om CC of \"nog geen grote pull\".",
	ACADEMY_TANK_RAID_TITLE = "Raids en LFR (later)",
	ACADEMY_TANK_RAID_BODY = "LFR is de zachte raid-intro: vergevingsgezind, veel healers. Focus op boss-taunt timings en staan op de juiste plek.\n\nMythic raid tanken is niet de volgende stap - eerst comfort in heroic/LFR.",
	ACADEMY_TANK_CHAT_TITLE = "Party chat",
	ACADEMY_CHAT_HINT = "Klik op een regel of het kopieer-icoon, daarna Ctrl+C om in party chat te plakken.",
	ACADEMY_CHAT_COPY_TIP = "Selecteer deze regel (Ctrl+C)",
	ACADEMY_TANK_CHAT_BODY = "\"Nog tank leren - rustig aan graag.\"\n\"Pull over 3...\"\n\"Even pauze voor mana.\"\n\"Interrupt op [spell] - ik pak volgende.\"\n\"Nog één try - die pull ken ik nu.\"",
	ACADEMY_TANK_LADDER_TITLE = "Angst-ladder (aanbevolen volgorde)",
	ACADEMY_TANK_LADDER_BODY = "1. Open world elites met een vriend\n2. Delves (kleinere instance - Delves-tab)\n3. Normal dungeon met mensen die je vertrouwt\n4. Heroic / LFR als het comfortabel voelt\n\nSla een stap over tot het saai wordt, niet eng.",
	ACADEMY_TANK_BOTH_TITLE = "Ook heal of DPS leren?",
	ACADEMY_TANK_BOTH_BODY = "Top - maar kies één hoofdrol in dungeons voorlopig. Oefen de andere rol in delves of open world.\n\nTank én heal in dezelfde M+ pug verdubbelt stress; één rol eerst geeft vertrouwen voor de tweede.",

	ACADEMY_HEAL_INTRO_TITLE = "Heal-mindset",
	ACADEMY_HEAL_INTRO_BODY = "Je bent niet verantwoordelijk voor iedereen op 100% HP de hele tijd.\n\nJe taak is triage: tank levend houden, degene die bijna dood is redden, dan de rest. Schade hoort erbij - paniek-overheal leegt mana.",
	ACADEMY_HEAL_TRIAGE_TITLE = "Triage (wie eerst?)",
	ACADEMY_HEAL_TRIAGE_BODY = "1. Jij (als jij sterft - dode healer heal niet)\n2. Tank (als de pack nog op hem zit)\n3. Iemand onder ~40% of met een fatale debuff\n4. De rest met efficiënte heals\n\nGrote heal na grote damage; kleine heals ertussen.",
	ACADEMY_HEAL_WIPE_TITLE = "Als het misgaat",
	ACADEMY_HEAL_WIPE_BODY = "\"Had ik de tank kunnen redden?\" is de nuttige vraag - niet \"waarom stond DPS in fire?\"\n\nGeen mana meer? Gebruik efficiëntere spells. Eén wipe betekent niet dat je niet kunt healen.",
	ACADEMY_HEAL_DUNGEON_TITLE = "Je eerste dungeon (normal)",
	ACADEMY_HEAL_DUNGEON_BODY = "Zeg dat je leert. Blijf in range van de tank; laat DPS een schrammetje nemen voordat je mana spuit.\n\nTussen pulls: drinken, buffen, ademen. \"Oom, 5 sec\" mag.",
	ACADEMY_HEAL_RAID_TITLE = "Raids en LFR (later)",
	ACADEMY_HEAL_RAID_BODY = "LFR: raid-wide damage wordt voorspelbaar na één wipe. Leer de fight-timer, niet elke speler-bar.\n\nRaid healen = dezelfde triage - tank en raid cooldowns eerst.",
	ACADEMY_HEAL_CHAT_TITLE = "Party chat",
	ACADEMY_HEAL_CHAT_BODY = "\"Heal leren - ik roep bij lage mana.\"\n\"Tank is prio - roep als je pauze wilt.\"\n\"Grote heal op jou - let op HP.\"\n\"Oom 5 sec tussen pulls.\"\n\"Dat was aan mij - volgende pull meer op tank.\"",
	ACADEMY_HEAL_LADDER_TITLE = "Angst-ladder (aanbevolen volgorde)",
	ACADEMY_HEAL_LADDER_BODY = "1. Heal een vriend in open world\n2. Delves met een kleine group\n3. Normal dungeon met geduldige vrienden\n4. Raid LFR / heroic als je er klaar voor bent\n\nDelves zijn de zachtste stap naar instances.",
	ACADEMY_HEAL_BOTH_TITLE = "Ook tank of DPS leren?",
	ACADEMY_HEAL_BOTH_BODY = "De DPS-track is de zachtste tweede rol - alleen je rotatie, kicks en positie, geen druk richting de groep. De Tank-track geeft de snelste dungeon-queue zodra tanken minder eng voelt.\n\nTwee rollen in één week in pugs is veel - kies er één als \"hoofdrol\" om angst te verminderen.",
	ACADEMY_DPS_BOTH_TITLE = "Denk je aan tank of heal?",
	ACADEMY_DPS_BOTH_BODY = "Je kent de fights al vanuit de DPS-stoel, en dat is het meeste werk. Tanken geeft je meteen een dungeon-queue; healen vraagt de meeste zenuwen maar is het meest gezocht.\n\nProbeer de nieuwe rol eerst in een delve of follower dungeon, waar niemand op je wacht. Houd daarna een tijdje één rol aan als hoofdrol in plaats van elke pug te wisselen.",

	-- Verdiepte beginner heal-course (healer-initiatief, deel 2)
	ACADEMY_HEAL_MANA_TITLE = "Mana en efficiëntie",
	ACADEMY_HEAL_MANA_BODY = "Mana is je échte health-bar. Raakt-ie leeg, dan kun je helemaal niet meer healen.\n\nGebruik goedkope, snelle heals voor kleine dipjes; bewaar je grote, dure heals voor echte noodgevallen. Niet iedereen hoeft op vol te zitten - laat mensen gerust op 80% lopen.\n\nDrink tussen elke pull. \"Oom, 5 sec\" zeggen is heel normaal en professioneel.",
	ACADEMY_HEAL_POSITION_TITLE = "Waar je gaat staan",
	ACADEMY_HEAL_POSITION_BODY = "Blijf binnen bereik van de hele groep, maar niet bovenop de boss. Een hoekje achterin waar je iedereen ziet is beter dan tegen de tank aan plakken.\n\nJij moet óók ontwijken. Een dode healer healt niemand - stap uit de troep, ook al kost het een halve seconde casten.\n\nHou zicht (line of sight): door een muur of pilaar heen healen kan niet.",
	ACADEMY_HEAL_COOLDOWNS_TITLE = "Bewaar je grote cooldowns",
	ACADEMY_HEAL_COOLDOWNS_BODY = "Je grote heal-cooldowns zijn voor grote, geplande schade - een raid-brede klap van de boss - niet voor willekeurige schrammetjes.\n\nEen cooldown het hele gevecht \"voor het geval dat\" bewaren is zonde. Een cooldown op 90% van het juiste moment is beter dan eentje die je nooit indrukt.\n\nTyp /mh healcds voor de cooldowns van jouw spec en wanneer je elke bewaart.",
	ACADEMY_HEAL_MISTAKES_TITLE = "Veelgemaakte beginnersfouten",
	ACADEMY_HEAL_MISTAKES_BODY = "1. Tunnelvisie op één health-bar terwijl er drie andere zakken\n2. Paniek-overhealen naar 100% en je mana leegtrekken\n3. In de troep blijven staan terwijl je naar de frames staart\n4. Je cooldowns nooit indrukken\n5. Door vermijdbare schade heen healen i.p.v. om een interrupt vragen\n\nKies er per run één om op te letten - niet alle vijf tegelijk.",
	ACADEMY_HEAL_CONFIDENCE_TITLE = "Iemand verliezen mag",
	ACADEMY_HEAL_CONFIDENCE_BODY = "Er gaat iemand dood terwijl jij healt. Élke healer die er is heeft mensen laten sterven - zo leer je waar de grenzen liggen.\n\nEén dode is geen wipe, en een wipe is geen oordeel over jou. Onthoud het ene dingetje dat je anders zou doen, en laat het dan los.\n\nGroepen onthouden een kalme healer die communiceert veel beter dan een perfecte.",

	-- DPS-track (Role Academy DPS-role)
	ACADEMY_DPS_INTRO_TITLE = "DPS-mindset",
	ACADEMY_DPS_INTRO_BODY = "Je taak is damage - maar een dode DPS doet nul. Overleven en mechanics doen komt eerst, damage tweede.\n\nJe hoeft niet bovenaan de meter te staan. Stabiele damage terwijl je je werk doet is beter dan enorme getallen gevolgd door een dood.",
	ACADEMY_DPS_ROTATION_TITLE = "Prioriteit, geen vaste rotatie",
	ACADEMY_DPS_ROTATION_BODY = "De meeste specs bouwen een resource op en geven die dan uit. Hou je builder en spender lopend; cap je resource niet en laat je dots/buffs niet wegvallen.\n\nEén of twee knoppen op het juiste moment is beter dan vijf rammen. Leer de prioriteit, niet een uit-je-hoofd-volgorde.",
	ACADEMY_DPS_COOLDOWNS_TITLE = "Lijn je cooldowns uit",
	ACADEMY_DPS_COOLDOWNS_BODY = "Je damage-cooldowns zijn het grootste deel van je schade. Ze op cooldown indrukken is beter dan bewaren voor een \"perfect\" moment dat nooit komt.\n\nOp een boss: open ermee of bewaar ze voor de fase die telt. Je toolkit hierboven toont ze voor jouw spec.",
	ACADEMY_DPS_MECHANICS_TITLE = "Mechanics winnen van damage",
	ACADEMY_DPS_MECHANICS_BODY = "Ga uit de troep, ook al kost het een cast. Een stapel vermijdbare schade wipet de groep sneller dan lage DPS.\n\nHebberig is nog één cast in het vuur blijven. Goed is een halve seconde herpositioneren en blijven leven om de rest te drukken.",
	ACADEMY_DPS_UTILITY_TITLE = "Je bent geen damage-robot",
	ACADEMY_DPS_UTILITY_BODY = "Interrupt gevaarlijke casts, gebruik je crowd control, en druk je eigen defensive als je een grote klap krijgt.\n\nEen DPS die kickt en overleeft is veel meer waard dan eentje die alleen getallen pompt.",
	ACADEMY_DPS_MISTAKES_TITLE = "Veelgemaakte beginnersfouten",
	ACADEMY_DPS_MISTAKES_BODY = "1. Op cooldowns blijven zitten \"voor het geval dat\"\n2. Je resource cappen (verspilde generatie)\n3. In de troep blijven voor nog één cast\n4. Nooit interrupten of utility gebruiken\n5. Tunnelvisie op damage terwijl je health leegloopt\n\nKies er per run één om op te lossen - niet alle vijf tegelijk.",
	ACADEMY_DPS_PRACTICE_TITLE = "Doelwit-oefening",
	ACADEMY_DPS_PRACTICE_BODY = "Sla twee minuten op een training dummy: hou je resource lopend, weef je cooldowns erin, en kijk wat wegvalt.\n\nDaarna delves, dan normal dungeons. Je hoeft geen perfecte rotatie om te beginnen - je moet blijven drukken en in leven blijven.",

