	CURIO_NOTE_DISCLAIMER = "Regels met >> zijn onze eigen lezing van de speltekst erboven - uit de bewoording, niet uit een run, en niet wat guides zeggen. Controleer ze zelf tegen de beschrijving.",
	CURIO_NOTE_SOULTHIRST = "Leech, Avoidance en Speed houden je in leven in plaats van sneller te doden - de keuze als een delve je blijft slopen.",
	CURIO_NOTE_FORGOTTEN = "Op papier de meeste schade, maar elke stack valt weg zodra de drager geraakt wordt - dit wil iemand die géén klappen krijgt.",
