	INFO_DRAWER_TOGGLE_HIDE = "Sluit",
	INFO_DRAWER_TITLE_FMT = "%s - Gebruik",
	INFO_DRAWER_BODY_DELVES = "Midnight Delves command center voor je huidige character.\n\nKlap Great Vault open voor weekly reward tracking, of Midnight Delves voor season currencies (Restored Coffer Keys, weekly Shards, Undercoins), Delver's Journey / renown en de volledige delve-lijst met live bountiful-detectie via map POI's.\n\nNavigatie: rechtermuisklik op een rij om naar de ingang te routen. |cffffcc00TomTom (aanbevolen)|r geeft de kaartpijl en waypoint-wachtrij. |cff00ff00Travel Assistant|r (popup als je ver weg bent) toont Hearthstone en hub-portals en werkt |cffffff00zonder|r TomTom.\n\nFind Nearest Bountiful vereist een geïnstalleerde TomTom.",
	INFO_DRAWER_BODY_ACCOUNT = "Cross-character overzicht lokaal opgeslagen door deze addon (saved variables op jouw PC — geen Blizzard cloud sync).\n\nPer rij: Keys, Shards, Undercoins, professions-echo en een compacte Great Vault-samenvatting met tooltips; je ingelogde character is gemarkeerd en sortering is op nut afgestemd.\n\nRijen verversen bij login en currency/weekly events. Verwijderen wist alleen addon snapshot-data — nooit je echte WoW-character.",
	INFO_DRAWER_BODY_RARES = "Midnight world rares per zone (Eversong, Zul'Aman, Harandar, Voidstorm).\n\nKies links een zone. Rijen: groen = af op dit character, groen UP = vignette bij spawn (waarschijnlijk up), grijs streepje = niet op je kaartdata.\n\nDichtstbijzijnde rare = één pin; Route genereren = alle open rares in TomTom (dichtstbij eerst, zoals Professions). UP via vignette is indicatief — open de zonekaart of kom dichterbij bij twijfel.",
	RARES_TITLE = "Midnight rares",
	RARES_SUBTITLE_FMT = "%d/%d af op dit character · %d nu op kaart (zilveren ster)",
	RARES_EMPTY_ZONE = "Geen rare-lijst voor deze zone.",
	RARES_BTN_NEAREST = "Dichtstbijzijnde rare",
	RARES_BTN_ROUTE = "Route genereren",
	RARES_NEAREST_ROUTE = "|cffffff78Midnight Helper:|r TomTom: dichtstbijzijnde rare — %s",
	RARES_NEAREST_NONE = "Geen open rares meer in deze zone.",
	SHARDS_REMAINING_FMT = "Coffer Key Shards: nog %d van %d te verdienen deze week - ongeveer %d rares.",
	SHARDS_CAP_REACHED = "Coffer Key Shards: weekcap bereikt. Rares leveren deze week niets meer op.",
	RARES_NEAREST_NO_TRAVEL = "Travel Assistant niet beschikbaar (Delves-module niet geladen).",
	RARES_ROUTE_DONE_FMT = "%d/%d open rares in TomTom gezet. %s",
	RARES_SKIP_DONE_FMT = "%s overgeslagen — pijl naar de volgende rare (je komt er later op terug).",
	RARES_SKIP_LAST = "Dit is de laatste open rare — niks om naar over te slaan.",
	RARES_SKIP_SINGLE = "Skip werkt tijdens Generate Route (schuift langs niet-gespawnde rares).",
	ARROW_OTHER_CONTINENT = "(ander continent — reis terug)",
	ARROW_CHAT_TRAVEL = "%s ligt niet op dit continent. Ga eerst naar %s.",
	ARROW_CHAT_TRAVEL_NOAIM = "%s ligt niet op dit continent — je zult eerst terug moeten reizen.",
	ARROW_LEAVE_INSTANCE_FIRST = "(eerst hier naar buiten)",
	ARROW_FLY_TO = "ga richting %s",
	ARROW_AT_STEP = "Je staat bij %s — loop erdoor, aan de andere kant pakt de pijl het weer op.",
	ARROW_TARGET_ROAMS = "|cffffd100(zwerft — kijk rond)|r",
	RARE_SPAWN_FROM_CHEST = "|cffffd100(open de kist om hem op te roepen)|r",
	ROUTE_CLEARED = "Route gewist.",
	ROUTE_CLEAR_NONE = "Geen actieve route om te wissen.",
	RARES_ROUTE_ORDER_NEAR = "Volgorde: dichtstbijzijnde eerst, daarna steeds de volgende.",
	RARES_ROUTE_ORDER_LIST = "Volgorde: lijst (positie niet beschikbaar).",
	RARES_TAG_UP = "UP",
	RARES_TAG_DOWN = "—",
	RARES_TIP_DONE = "Deze week af op dit character (reset woensdag).",
	RARES_TIP_UP = "Waarschijnlijk up (map-vignette bij spawn).",
	RARES_TIP_DOWN = "Nu niet op je kaart — kan later alsnog spawnen.",
	RARES_TIP_VIGNETTE_NOTE = "Vignette-status is indicatief; open de zonekaart of kom dichterbij.",
	INFO_DRAWER_BODY_SMC = "Silvermoon City referentie voor Midnight (map 2393). Dezelfde scroll begint met Weekly / hub checklist zodra quest IDs geconfigureerd zijn, gevolgd door pin-grids per categorie — Essential Services, Travel, Quest hubs, Profession trainers, Gathering, enz.\n\nElke locatie-knop zet Blizzards user waypoint en, met TomTom, dezelfde pin via de slash helper (/way #2393 …).\n\nVoortgang in de checklist kleurt gekoppelde waypoint-knopen groen; verifieer quest IDs na grote patches als iets niet klopt.",
	INFO_DRAWER_BODY_PROFESSIONS = "Volgt Midnight Knowledge Points (KP) voor je huidige character, plus currency-regels als de client ze geeft (Unalloyed Abundance, Artisan's Moxie, weekly Shards of Dundun).\n\nDaaronder twee kolommen met Knowledge Pickup quests en profession books per trade — iconen tonen of de quest af is. Klik een rij om alleen die pin naar TomTom te sturen (andere waypoints worden gewist; Travel Assistant voor zone-hops als TomTom geladen is).\n\nOnderaan: Generate Treasures / Generate Books om alle open pins in één keer te queuen (dichtstbijzijnde onafgeronde eerst als je map-positie bekend is).",
	INFO_DRAWER_BODY_GUIDE = "Spec-voor-spec leveling referenties in Icy Veins-stijl: stat priority, gear-keuzes, consumables gefilterd op je level, optionele spell-tipregels en Leveling Advisor met brackets voor rotatie, defensives en talentfocus.\n\nHeeft je class een Midnight key-map (nu Hunter / Paladin), dan tonen tips soms een gouden toets-knop — klik om naar Indeling te gaan en die toets op het toetsenbord te zien. Zo koppel je uitleg (wát je drukt) aan plek (waar op het keyboard), en leer je door te doen.\n\nDe globale zoekbalk herkent keywords en kan tussen Midnight Helper-tabs springen; Preview laat een andere specialisatie zien zonder relog, Mijn character zet terug naar je actieve spec.\n\nZichtbaarheid volgt Settings: Auto (verbergt vanaf level 90+), Altijd tonen of Altijd verbergen.",
	INFO_DRAWER_BODY_MACROS = "Tab Interrupt: team kick-macro (eerst focus). Tab Utility: extra spec-macros (cursor-grondspells, mouseover heals, enz.) uit het team-pakket. Kies een rij, lees de tip, kopieer de tekst.\n\nData kan na patches wijzigen - meld ontbrekende spells aan het team.",
	INFO_DRAWER_BODY_ADDONS = "Hub voor optionele tools die in Midnight Helper zitten i.p.v. losse downloads.\n\nKies een sub-tab bovenaan — nu Platynator: Wago-link, profile-string import en de MF Platynator visual gallery.\n\nToekomstige partner-panelen verschijnen hier automatisch als ze worden toegevoegd.",
	ABOUT_WINDOW_TITLE = "Over Midnight Helper",
	ABOUT_VERSION_FMT = "Geïnstalleerde versie: |cffffcc00%s|r",
	ABOUT_WINDOW_BODY = "Auteurs: TwelveInchy & Claude\n\nJe alles-in-één Midnight-metgezel, ingedeeld in vier kamers — Me, Codex, Tools en Settings. Pin favorieten onder de zoekbalk en typ om overal heen te springen. Met Deze week, Delves & Vault, Delve- & Ritual-coaches, de Enchants & Gems-advisor, Account snapshot, Codex-guides, Professies en geïntegreerde addon-tools — EN / NL / DE / FR / ES / PT / IT.\n\nMet dank aan de addons en guides waartegen we onze feiten gecontroleerd hebben: EXBoss en EXBossData (key casts van raidbosses), HandyNotes_Midnight (locaties van rares en schatten), GTFO (spell-id's van hazards), RareScanner (omgang met vignettes), en Wowhead, Icy Veins en Method. We nemen id's en getallen als aanwijzing en bevestigen ze in de client voordat ze hier terechtkomen; er wordt geen code van deze addons gebruikt.",
	MAIN_TITLE_VERSION_FMT = "v%s",
	BROKER_TOOLTIP_VERSION_FMT = "Versie: %s",

	CHANGELOG_TITLE = "Midnight Helper Changelog",
	CHANGELOG_SUBTITLE = "Versie %s",
	CHANGELOG_VERSION_FMT = "Versie %s",
	CHANGELOG_CLOSE = "Sluiten",
	CHANGELOG_CB_UNTIL_NEXT = "Niet opnieuw tonen tot volgende versie",
	CHANGELOG_CB_NEVER = "Changelog permanent verbergen",
	CHANGELOG_ASK = "Klopt er iets niet in deze lijst, of mist er iets voor jouw klasse? Eén persoon schrijft deze addon — zeg het op Discord of GitHub, dan wordt het gerepareerd.",
	CHANGELOG_120_1 = "Compact Leveling Advisor-paneel toegevoegd met level-brackets en tabbladen (Rotatie / Verdediging / Talentfocus).",
	CHANGELOG_120_2 = "Consumables-sectie verbeterd: toont alleen bruikbare items op je huidige level en meldt volgende unlocks.",
	CHANGELOG_120_3 = "Account Snapshot-beheer toegevoegd: oude characters veilig verwijderen (met bevestiging) plus zebra-strepen.",
	CHANGELOG_120_4 = "Lokalisatieconsistentie (EN/NL) verbeterd en in-guide stat-woordenlijst toegevoegd via de nieuwe ? Stats-knop.",
	CHANGELOG_121_1 = "Hoofdvenster: panelen blijven binnen de gouden dialoogrand — hoekversiering blijft zichtbaar en de extra lege strook rechts/onder naast de resize-greep is weg.",
	CHANGELOG_121_2 = "Info en About gebruiken weer standaard Blizzard-panelknoppen (zelfde stijl als Zoeken / Mijn character) voor een gelijk beeld op alle clients.",
	CHANGELOG_121_3 = "Alleen kleine UI-polish; Delves, Vault, guides en lokalisatie niet gewijzigd — veilige update.",
	CHANGELOG_122_1 = "Macros-tab: team-interrupt in één klik, plus handige utility-macro's per spec (cursor, mouseover, focus)—kopieer, plak, speel.",
	CHANGELOG_122_2 = "Andere spec bekijken zonder relog: zoeken in de guide werkt leveling-tips, toetsenbord-layout én macro's in één keer bij.",
	CHANGELOG_122_3 = "Guide-zoeken en chatmeldingen volgen je taal (/mh lang en of nl).",
	CHANGELOG_122_4 = "Midnight-toetsenlayout: interrupt op E, duidelijkere rollen, slimmere overflow (Alt, Shift, Ctrl).",
	CHANGELOG_122_5 = "Nog in de oven: alles in Midnight Helper kan veranderen en wordt steeds beter—updates blijven komen. Feedback is welkom!",
	CHANGELOG_182_4 = "Nieuwe Omnium Folio-tab: de volledige 12.0.7 rune-tree met klikbare spell-tooltips, een aanbevolen keuze per rij voor M+/Raid/PvP/Wereld, de unlock-uitleg en een live x/5-rijen-ontgrendeld-teller. De Account snapshot-checklist herinnert je nu ook (account-breed) aan deze week's Folio-Mote tot je volledig ontgrendeld bent.",
	CHANGELOG_185_1 = "Nieuwe instelling: de wekelijkse Coffer Shard-cap-popup verbergen (Instellingen -> Dungeon). Met dank aan gadrinonturalyon voor het verzoek!",
	CHANGELOG_185_2 = "Nieuwe instelling: het 3D-bossmodel in het boss-venster tonen of verbergen (Instellingen -> Dungeon). Ook aangevraagd door gadrinonturalyon.",
	CHANGELOG_185_3 = "Nieuwe taal: Italiaans (itIT) — interface en gidsen vertaald. Automatisch op een Italiaanse WoW-client, of kies 'm met /mh lang it. (Oudere changelog-regels blijven Engels.)",
	CHANGELOG_185_4 = "Opgelost: de world-boss-regel \"Warband: deze week verslagen\" verschijnt nu op al je characters zodra één ervan de boss doodt (account-brede check), niet alleen op de character die lootte — en onthoudt welke character het deed.",
	CHANGELOG_185_5 = "Opgelost: de wekelijkse Coffer Shard-cap-popup verschijnt nu maar één keer per character per week. Na deze update zie je 'm mogelijk nog één keer, daarna blijft 'ie uit tot de volgende reset (als je de cap opnieuw haalt).",
	CHANGELOG_185_6 = "Nieuw in Professions 101: een 'Skill leveling 1-100'-route per professie (eerst Alchemy & Herbalism, meer volgt) en een duidelijk 'Work Orders uitgelegd'-hoofdstuk - hoe je items bestelt en voor anderen craft.",
	CHANGELOG_186_1 = "Nieuw: de groepsleider kan met /mh boardall ieders consumable-bord oproepen, zodat de hele groep flasks, runes en food opnieuw kan checken.",
	CHANGELOG_186_2 = "Nieuw: een 'Eindbaas - open coach?'-knopje verschijnt bij een boss-gevecht als je de Delve Coach eerder in die delve had weggeklikt.",
	CHANGELOG_184_1 = "Consumable-bord vernieuwd: echte item- & spell-iconen met status, aantallen en buff-timers. Klik je eigen consumables — of je class-buff — om ze direct vanaf het bord te gebruiken.",
	CHANGELOG_184_2 = "Raid- & class-buffs op het bord: Arcane Intellect, Battle Shout, Power Word: Fortitude, Mark of the Wild en Skyfury. Hover een buff voor precies wie 'm heeft en wie 'm mist (hele groep, ook cross-faction).",
	CHANGELOG_184_3 = "Slimmere kolommen: het bord toont alleen wat relevant is — Healthstone alleen bij een Warlock, weapon-olie alleen voor specs die 'm gebruiken, zonder gaten.",
	CHANGELOG_184_4 = "De consumable-check verschijnt nu ook bij een ritual of delve (niet alleen dungeons), en je heropent het bord met een middel-klik op de minimap-knop.",
	CHANGELOG_184_5 = "Food (Well Fed)-detectie dekt nu élke food, en als je een slot mist toont de hover het aanbevolen item met een 'niet in je tas'-melding.",
	CHANGELOG_184_6 = "Opgelost: de Omnium Folio-ontgrendel-teller telt nu account-breed, zodat alts niet meer 0/5 tonen terwijl de rijen op je account al open zijn.",
	CHANGELOG_184_7 = "Opgelost: de delve/ritual-death-teller reset niet meer na een /reload; een Lua-fout door 12.x 'secret' aura-waarden; en de catalyst heet nu correct de Matrix Catalyst, inclusief hoe je 'm ontgrendelt.",
	CHANGELOG_183_1 = "Consumable-check: bij het binnengaan van een dungeon checkt MH je flask, augment rune, potions, food en healthstone — plus de buffs van de groep — met ready-check-iconen. /mh readycheck om te draaien, /mh readytoggle of de nieuwe instelling om te dempen. Toont '?' i.p.v. een onterechte 'ontbreekt' als een slot niet leesbaar is.",
	CHANGELOG_183_2 = "Daggerspine Point opent nu automatisch het zwevende boss-venster bij elke boss (Mindbreaker, Selen'vjar), net als de andere dungeons.",
	CHANGELOG_183_3 = "Nieuw Codex-artikel: de Ritual Sites Renown-track — wat elk van de 8 ranks ontgrendelt (orbs, treasures, decor, shrines, pets, de Void-Touched Hawkstrider) en waarom een hogere-rank-site meer oplevert.",
	CHANGELOG_183_4 = "Omnium Folio-tab: een nieuwe knop 'Open rune-venster' opent de Folio direct — handig als je UI de minimap-expansieknop verbergt (bv. Ellesmere).",
	CHANGELOG_183_5 = "De Folio-weekly-herinnering vertelt nu wát de Mote van deze week vraagt (bv. verzamel Ritualized Arcana van Ritual-Site-elites).",
	CHANGELOG_183_6 = "Ritual Sites-renown-vendors Rae'ana (decor) en Sergeant Vornin (pets & mount) zijn nu klikbare waypoints in Silvermoon.",
	CHANGELOG_183_7 = "Opgelost: de Omnium Folio-ontgrendel-teller (en de Folio-weekly-herinnering) tellen nu account-breed, zodat alts niet meer 0/5 tonen terwijl de rijen op je account al open zijn.",
	CHANGELOG_183_8 = "Consumable-bord: bij het binnengaan van een dungeon verschijnt een zwevend bord met de ready-check-iconen per groepslid. Sleepbaar, SHIFT+scroll om te zoomen; verbergt bij de pull. /mh readyboard opent het handmatig.",
	CHANGELOG_183_9 = "Groeps-tasdeling: groepsleden met Midnight Helper delen hun tas-status, zodat je hun flask/rune/potions/food/healthstone ziet i.p.v. 'bag unknown'.",
	CHANGELOG_183_10 = "Food-check toegevoegd, en je flask/rune tonen nu groen voor de aanbevolen best voor je spec, amber voor een alternate.",
	CHANGELOG_182_1 = "Zwevend boss-venster: met de X sluiten laat nu alléén die ene boss met rust — de volgende boss geeft een vers venster (een nieuwe pull, een ritual-stage of de boss simpelweg targeten). Permanent uit via de nieuwe schakelaar hieronder.",
	CHANGELOG_182_2 = "Nieuwe 'Automatisch openen'-schakelaar voor het boss-venster (Dungeon Coach-instellingen): zet 'm uit om het nooit vanzelf te openen; via /mh bosswin opent hij nog steeds.",
	CHANGELOG_182_5 = "Great Vault-advisor: de tier-set-note is nu drempel-bewust — hij zegt of een vault-tier-stuk je 2- of 4-set-bonus voltooit, of gewoon een extra stuk is zonder nieuwe bonus (dan kan een stat-upgrade beter zijn).",
	CHANGELOG_182_3 = "Lua-fout in ritual-scenario's op 12.x verholpen (boss-unit-ID's zijn nu 'secret' values en konden de execution tainten en crashen).",
	CHANGELOG_181_1 = "Nieuwe Tier Sets-tab: je class-set, je 2- en 4-set-bonussen (hover voor de live tooltip) en een live teller van hoeveel tier-stukken je draagt.",
	CHANGELOG_181_2 = "Nieuwe Valuta-tab — waar verdien én geef je elke Midnight-currency uit, met live saldo's. Vendor-namen zijn nu klikbaar voor een TomTom-waypoint (door de hele addon).",
	CHANGELOG_181_3 = "Rare-doodshoofd: route naar een rare via de melding en er komt een skull op z'n nameplate zodra je aankomt — meteen herkenbaar.",
	CHANGELOG_181_4 = "Rustiger, strakker beeld: één goud, rol-iconen i.p.v. een kleur-regenboog bij boss-stappen, zachtere links, en tooltips verschijnen nu bij je cursor.",
	CHANGELOG_181_5 = "Nieuwe 'Eenvoudige weergave'-knop bovenaan het menu — verberg alles behalve de kerntabs (ideaal voor nieuwe spelers); één keer instellen, onthouden op al je characters.",
	CHANGELOG_181_6 = "Plus de Val & Naigtal Showdown-rares, een Enchants-tab met één-klik Auction House-kopie, en fixes (world-boss 'verslagen'-regel over alts, enchant-paneel-refresh, en meer).",
	CHANGELOG_180_1 = "Raid- & Mythic+-coaches: beginner-boss-stappen voor alle nieuwe raids (klikbare casts), plus een Mythic+-tab met must-interrupts en een Beginnersmodus + woordenboek.",
	CHANGELOG_180_2 = "Nieuwe Enchants-tab: checkt je gear op ontbrekende enchants en stelt er één voor je spec voor — klik een suggestie om de naam te kopiëren voor het Auction House.",
	CHANGELOG_180_3 = "Nieuwe Valuta-tab: waar verdien én geef je elke Midnight-currency uit, met je live saldo's en een waypoint naar elke Renown Quartermaster.",
	CHANGELOG_180_4 = "Nieuwe Events-tab: elk wereld-event met live timers, klik-om-te-routen, en Shift-klik voor 3D-beloningspreviews.",
	CHANGELOG_180_5 = "Opt-in Helper alerts, een Delve & Ritual-log, en een fix zodat de wereldboss 'deze week verslagen'-regel klopt voor je hele warband.",
	CHANGELOG_171_1 = "Zwevend boss-venster met 3D-model, en elke boss-stap leest nu native in alle zes talen.",
	CHANGELOG_170_1 = "Dungeons-tab: de Dungeon Coach (boss-stappen voor alle 12 dungeons) en een Dungeons 101-beginnerscursus.",
	CHANGELOG_170_2 = "Rare-alert opgevoerd: een versleepbare 3D-model-toast, plus een wekelijkse Coffer Shard-cap-melding.",
	CHANGELOG_170_3 = "De 'After the reset'-routine begrijpt nu low-level characters.",
	CHANGELOG_160_1 = "'After the reset'-routine op Home, met een one-click TomTom-route langs alles wat je nog open hebt staan.",
	CHANGELOG_160_2 = "Per-slot Great Vault-detail op elke alt, en een Ritual Coach die tips deelt in de eigen taal van je groepsgenoten.",
	CHANGELOG_160_3 = "Wekelijkse tracking voor alle 11 professions, en een Start Here-roadmap voor je eerste week.",
	CHANGELOG_155_1 = "Keybind-fix: staat onder Toetsen → Midnight Helper (niet Other); standaard Alt+M; zelfde werking als /mh.",
	CHANGELOG_154_1 = "Keybind: Esc → Toetsen → AddOns → Midnight Helper → Hoofdvenster openen/sluiten (handig voor Stream Deck, geen macrobalk nodig).",
	CHANGELOG_153_1 = "World boss: weekstatus klopt weer na reset — kill van vorige week wordt niet meer als deze week getoond.",
	CHANGELOG_153_2 = "World boss: login Lua-fout opgelost (cache-opruiming bij opstarten).",
	CHANGELOG_153_3 = "Fix: geen Lua-fouten in delves bij nameplate-tooltips (delve-story-hook; uit 1.5.2).",
	CHANGELOG_152_1 = "Fix: geen Lua-fouten meer in delves als nameplate-addons (bv. Platynator) aura-tooltips tonen — delve-story-hook alleen op kaart-POI-tooltips.",
	CHANGELOG_152_2 = "Delve-story-detectie blijft via wereldkaart / Area POI; geheime tooltip-ID's worden veilig overgeslagen op 12.x.",
	CHANGELOG_151_1 = "Midnight Codex (beta-tab): Season 1-handboek met live valuta-saldi, Blizzard-tooltips en Open-knoppen naar de juiste addon-tabs.",
	CHANGELOG_151_2 = "Codex in het beta-blok in de zijbalk — aan/uit via Esc → AddOns → Midnight Helper (per tab + hoofdschakelaar).",
	CHANGELOG_151_3 = "Home: delve-weektrackers (Trovehunter's Bounty, Gilded Stash, Special Assignments) met account-alt-rollup.",
	CHANGELOG_151_4 = "Delve Coach: kiest automatisch de actieve baas in multi-boss-delves; blader in de sessie zonder live detectie te breken.",
	CHANGELOG_151_5 = "Delve Coach: live delve-baas-3D-preview en story-variant-detectie verbeterd (map-tooltip, Grudge Pit / arena-fallbacks).",
	CHANGELOG_151_6 = "Fix: Trovehunter's Bounty zegt niet meer \"gebruik hem!\" op Home tenzij de kaart echt in je tassen zit.",
	CHANGELOG_150_1 = "Home-tab (standaard bij openen): countdown tot weekly reset, account Great Vault, world boss, weektaken en snelkoppeling naar Rares.",
	CHANGELOG_150_2 = "Rares-tab: weekly tracking per character, dichtstbijzijnde rare of volledige route (echte yards over kaarten heen).",
	CHANGELOG_150_3 = "TomTom-route: de pijl blijft op de dichtstbijzijnde waypoint in plaats van naar de laatst toegevoegde pin te springen.",
	CHANGELOG_150_4 = "Live rare-alerts: geluid + toast als een gevolgde rare in de buurt is (~500 yd), ook met het hoofdvenster dicht.",
	CHANGELOG_150_5 = "Klik op de toast voegt die rare toe als extra waypoint zonder je lopende route te wissen.",
	CHANGELOG_150_6 = "Zijbalk in secties gegroepeerd; Reference heet nu Basics; minimale vensterhoogte zodat tabs About niet overlappen.",
	CHANGELOG_140_1 = "Great Vault Advisor: rangschikt vault-loot op Blizzard's Great Vault-scherm (ilvl, guide-stats, tier sets). Auto / Raid / M+ profielen; optioneel Pawn.",
	CHANGELOG_140_2 = "Beta-zijbalktabs: Guide, Leveling Guides, Macros en Role Academy tussen Professions en Consumables—aan/uit via Esc → AddOns → Midnight Helper.",
	CHANGELOG_140_3 = "Vault-herinneringen: chat-samenvatting, minimap-ping en login-popup in addon-instellingen.",
	CHANGELOG_140_4 = "UI voor advisor en beta-instellingen in zes talen (EN DE FR ES PT NL).",
	CHANGELOG_140_5 = "Fixes: beta-tab vinkjes geven geen Lua-fouten meer.",
	CHANGELOG_130_1 = "Delve Party Share: deel delve-tips in party-, raid- of instance-chat vanuit Delve Coach (briefing, baas, secties, kopieer). Test (/say) solo.",
	CHANGELOG_130_2 = "Delve-items popup: RAID-R Mini en Trovehunter's Bounty in delves—auto paneel + minimap (alleen in delve; links = popup, rechts = gebruiken).",
	CHANGELOG_130_3 = "Delve Coach: Shift + muiswiel schaalt het hele paneel (zoals Midnight Helper). Sleep hoek, onderrand of rechterrand; wiel scrollt tips.",
	CHANGELOG_130_4 = "Bazen in beeld: betrouwbare preview bij eerste open, fix laadtekst, opgeslagen zoom per baas.",
